--
-- Name: aggregate_features(overwatch.id_type_pair[]); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.aggregate_features(pairs overwatch.id_type_pair[]) RETURNS json
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (
        WITH data AS (
            SELECT pair.type, json_array_elements(feature_collection::json->'features') AS feat
            FROM premade_geozones, UNNEST(pairs) pair
            WHERE premade_geozones.id = pair.id AND premade_geozones.type = pair.type
        )
        SELECT json_build_object(
            'type', 'FeatureCollection',
            'features', json_agg(
                json_build_object(
                    'type', 'Feature',
                    'geometry', ST_AsGeoJSON(ST_GeomFromGeoJSON(feat->>'geometry'))::json,
                    'properties', feat->'properties'
                )
            )
        ) as aggregated_features
        FROM data
    );
END;
$$;


--
-- Name: alerter_hit_users(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.alerter_hit_users(hit_id_param bigint) RETURNS SETOF overwatch.hit_user
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
BEGIN
    RETURN QUERY
     WITH
        hit_data AS (
            SELECT hits.id, integration_id
            FROM public.hits
            JOIN public.hotlist ON hotlist.id = hits.hotlist_id
            WHERE hits.id = hit_id_param
        ),
        settings_matching_hit AS (
            SELECT *
            FROM overwatch.alert_settings
            JOIN LATERAL (SELECT integration_id FROM hit_data) integration ON TRUE
            WHERE (integration.integration_id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings->'hotlists')::text)))
              AND alert_settings.type = 1
              AND alertable_type in ('integrations', 'user')
              AND settings->'notifications'->'alerter' IS NOT NULL
              AND settings->'notifications'->'alerter' != '[]'::jsonb
              AND alert_settings.deleted_at IS NULL
        ),
        alerter_users AS (
            SELECT DISTINCT
                jsonb_array_elements_text(settings_matching_hit.settings->'notifications'->'alerter')::bigint AS user_id, settings_matching_hit.id as setting_id
            FROM settings_matching_hit
        )
    SELECT
        DISTINCT users.id AS user_id,
        users.org_id AS org_id,
        hits.id AS hit_id,
        uc.id::bigint AS camera_id,
        uc.name AS camera_name,
        uc.is_commercial,
        uc.is_shared
    FROM public.integrations_view iv
    JOIN public.hotlist ON hotlist.integration_id = iv.id
    JOIN public.hits ON hits.hotlist_id = hotlist.id
    JOIN public.scans ON hits.scan_id = scans.id
    JOIN overwatch.users ON overwatch.users.org_id = iv.org_id AND overwatch.users.deleted_at IS NULL
    JOIN alerter_users ON alerter_users.user_id = users.id
    JOIN overwatch.user_cameras2(users.id::bigint) uc ON scans.kit_id = uc.id
    JOIN settings_matching_hit ON alerter_users.setting_id = settings_matching_hit.id
    WHERE
        hits.hit_type = 'O'
        AND (
            (settings_matching_hit.settings->'cameras' IS NULL OR settings_matching_hit.settings->'cameras' = '[]'::jsonb)
            OR (
                uc.id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'cameras')::text))
                OR (
                    '-1'::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'cameras')::text))
                    AND uc.is_commercial = TRUE
                )
            )
        )
        AND (
            (settings_matching_hit.settings->'geozones' IS NULL OR settings_matching_hit.settings->'geozones' = '[]'::jsonb)
            OR (
                EXISTS (
                    SELECT 1
                    FROM overwatch.geo_zones
                    WHERE geo_zones.id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'geozones')::text))
                    AND public.st_within(scans.geo, geo_zones.geom)
                )
            )
        )
        AND (
            (settings_matching_hit.settings->'states' IS NULL OR settings_matching_hit.settings->'states' = '[]'::jsonb)
            OR (
                hotlist.us_state::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'states')::text))
            )
        )
        AND hits.id = hit_id_param;
END;
$$;


--
-- Name: hit_users(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.hit_users(hit_id_param bigint) RETURNS SETOF overwatch.hit_user
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

BEGIN
    return query
with
    hit_data as (select hits.id, integration_id
                 from public.hits
                     join public.hotlist on hotlist.id = hits.hotlist_id
                     where hits.id = hit_id_param),
    settings_matching_hit as (
   select * from overwatch.alert_settings
        join lateral ( select integration_id from hit_data)  integration on true
         where (integration.integration_id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings->'hotlists')::text)))
           and alert_settings.type = 2 and alertable_type = 'user' and alert_settings.deleted_at is null)
select
      users.id as user_id,
      users.org_id as org_id,
       hits.id as hit_id,
       uc.id::bigint as camera_id,
       uc.name as camera_name,
       uc.is_commercial,
       uc.is_shared
from public.integrations_view iv
join public.hotlist on hotlist.integration_id = iv.id
join public.hits on hits.hotlist_id = hotlist.id
join public.scans on hits.scan_id = scans.id
join overwatch.users on overwatch.users.org_id = iv.org_id and overwatch.users.deleted_at is null
join settings_matching_hit on settings_matching_hit.alertable_id = users.id
join overwatch.user_cameras2(users.id::bigint) uc on scans.kit_id = uc.id

--      join LATERAL(
--     select 1 from public.scans_meta where hits.scan_id = scans_meta.scan_id
--          and scans_meta.meta_type = 5  and (hotlist.us_state = scans_meta.meta_value or hotlist.us_state = '')
--                              ) as scans_meta_not_state on true
-- join LATERAL (
--     select 1 from public.scans_meta where hits.scan_id = scans_meta.scan_id
--          and scans_meta.meta_type = 4 and meta_value <> 'True'
--                              ) as scans_meta_not_plate on true
where
    hits.hit_type = 'O'
  and (
      (settings_matching_hit.settings->'cameras' is null or settings_matching_hit.settings->'cameras' = '[]'::jsonb)
        or
        (
      uc.id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings -> 'cameras')::text))
        or
        ('-1'::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings -> 'cameras')::text))
            and uc.is_commercial = true
            )
      ))
  and (
        (settings_matching_hit.settings -> 'geozones' is null or settings_matching_hit.settings -> 'geozones' = '[]'::jsonb)
        or
        (
            exists(
                select 1
                   from overwatch.geo_zones
                   where geo_zones.id::varchar = ANY
                         (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'geozones')::text))
                     and public.st_within(scans.geo,geo_zones.geom)
                   )
        )
    )
   and (
       (
      (settings_matching_hit.settings->'states' is null or settings_matching_hit.settings->'states' = '[]'::jsonb)
        or
        (
      hotlist.us_state::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings -> 'states')::text))

      ))
    )
    and hits.id = hit_id_param;
END;
$$;


--
-- Name: insert_overwatch_camera_func(); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.insert_overwatch_camera_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
   INSERT into public.kits (name,org_id,kit_mapping,kit_type) values (NEW.name, NEW.org_id,NEW.kit_mapping,NEW.kit_type) returning id into NEW.id;
   INSERT INTO cameras(id, location_id,properties, created_at, updated_at) values (NEW.id, NEW.location_id,properties, now(), now());
   RETURN NEW;
END;
   $$;


--
-- Name: manage_org_cameras_view(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.manage_org_cameras_view(p_org_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    org_name TEXT;
    view_name TEXT;
    view_sql TEXT;
    result_message TEXT;
    grant_sql TEXT;

BEGIN


    SELECT name INTO org_name
    FROM public.orgs
    WHERE id = p_org_id;

    IF org_name IS NULL THEN
        RAISE EXCEPTION 'No eligible organization found with org_id %', p_org_id;
    END IF;


    -- Sanitize name for use in view SQL identifier
    view_name := 'org_' || p_org_id || '_cameras';

    IF EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = 'overwatch' AND matviewname = view_name
    ) THEN
        -- Refresh if exists
        view_sql := format('REFRESH MATERIALIZED VIEW overwatch.%I;', view_name);
        EXECUTE view_sql;
        result_message := format('Refreshed materialized view: %s', view_name);

    ELSE
        -- Create if not exists
        view_sql := format(
                'CREATE MATERIALIZED VIEW overwatch.%I AS ' ||
                'SELECT oc.*, l.id as location_id, l.site_id, %L::bigint as pivot_key_id ' ||
                'FROM overwatch.org_cameras_v2(%L) as oc ' ||
                'left join overwatch.cameras on cameras.id = oc.id ' ||
                'left join overwatch.locations l on cameras.location_id = l.id;',
                view_name,
                p_org_id,
                p_org_id
                    );

        EXECUTE view_sql;
        result_message := format('Created materialized view: %s', view_name);
        grant_sql := format(
                'alter materialized view overwatch.%I owner to overwatch',
                view_name
                     );
        EXECUTE grant_sql;

    END IF;
    RETURN result_message;

END;
$$;


--
-- Name: org_cameras(bigint, boolean, boolean); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.org_cameras(org_id_param bigint, commercial boolean DEFAULT true, owned boolean DEFAULT true) RETURNS SETOF overwatch.user_camera
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

DECLARE
    org_type_variable INT;
    org_commercial_data_feed_variable BOOLEAN;

BEGIN
    select orgs.type,
           CASE WHEN org_meta.properties->>'commercial_data_feed' = 'true' THEN true ELSE false END
    from public.orgs
             left join public.org_meta on orgs.id = org_meta.id
    where orgs.id = org_id_param into org_type_variable, org_commercial_data_feed_variable;

    IF commercial = TRUE and owned = TRUE THEN

        RETURN QUERY
            with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_param))

            select kits.id,
                   kits.name,
                   kits.kit_type,
                   kits.org_id,
                   false as is_commercial,
                   false as is_shared
            from public.kits
                     join overwatch.cameras on cameras.id = kits.id
                     join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_param and cameras.deleted_at is null

            UNION ALL
            select * from org_shared_cameras
            UNION ALL

            -- DEV-1512: Added LEFT JOIN to org_meta on source org to filter by aggregated_data_sharing
            select kits.id,
                   'Commercial'::varchar as name,
                   kits.kit_type,
                   kits.org_id,
                   true as is_commercial,
                   false as is_shared
            from public.kits
                     join public.orgs on orgs.id = kits.org_id
                     left join public.org_meta as source_org_meta on source_org_meta.id = kits.org_id
            where org_id != org_id_param
              and orgs.type != 4
              and org_commercial_data_feed_variable = true
              and kits.id not in (select id from org_shared_cameras)
              and coalesce(source_org_meta.properties->>'aggregated_data_sharing', 'true') != 'false'
        ;

    ELSEIF commercial = TRUE AND owned = FALSE THEN
        RETURN QUERY
            with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_param))
            -- DEV-1512: Added LEFT JOIN to org_meta on source org to filter by aggregated_data_sharing
            select kits.id,
                   'Commercial'::varchar as name,
                   kits.kit_type,
                   kits.org_id,
                   true as is_commercial,
                   false as is_shared
            from public.kits
                     join public.orgs as po on po.id = kits.org_id
                     left join public.org_meta as source_org_meta on source_org_meta.id = kits.org_id
            where org_id != org_id_param and po.type != 4 and org_commercial_data_feed_variable = true
              and kits.id not in (select id from org_shared_cameras)
              and coalesce(source_org_meta.properties->>'aggregated_data_sharing', 'true') != 'false'
        ;


    ELSEIF commercial = FALSE AND owned = TRUE THEN
        RETURN QUERY
            select kits.id,
                   kits.name,
                   kits.kit_type,
                   kits.org_id,
                   false as is_commercial,
                   false as is_shared
            from public.kits
                     join overwatch.cameras on cameras.id = kits.id
                     join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_param
            UNION ALL
            select * from overwatch.org_shared_cameras(org_id_param);
    END IF;


END; $$;


--
-- Name: org_cameras_v2(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.org_cameras_v2(org_id_param bigint) RETURNS TABLE(id integer, name character varying, kit_type integer, org_id bigint, is_commercial boolean, is_shared boolean, scope jsonb)
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE
    org_type_variable INT;
    org_commercial_data_feed_variable BOOLEAN;
BEGIN
    -- Get organization type and commercial data feed setting
    SELECT orgs.type,
           CASE WHEN org_meta.properties->>'commercial_data_feed' = 'true' THEN true ELSE false END

    FROM public.orgs
             LEFT JOIN public.org_meta ON orgs.id = org_meta.id
    WHERE orgs.id = org_id_param
    INTO org_type_variable, org_commercial_data_feed_variable;
    RETURN QUERY

        with shared_cameras as (
            SELECT distinct kits.id,
                            kits.name,
                            kits.kit_type::integer,
                            kits.org_id::bigint,
                            false as is_commercial,
                            true as is_shared,
                            shared.scope::jsonb as scope
            FROM public.kits
                     JOIN overwatch.cameras ON cameras.id = kits.id
                     JOIN overwatch.shared ON shared_id = kits.org_id AND shared_type = 'org_cameras'
            WHERE shared_with_id = org_id_param
              AND shared_with_type = 'org'
              AND (shared.expires_at IS NULL OR shared.expires_at > now())
              AND status_id = 1
              AND cameras.deleted_at IS NULL
              AND shared.deleted_at IS NULL
              and kits.org_id != org_id_param
        )

        -- Owned cameras
        SELECT kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               false as is_shared,
               scope
        FROM public.kits
                 JOIN overwatch.cameras ON cameras.id = kits.id
                 JOIN overwatch.locations ON locations.id = cameras.location_id
        WHERE kits.org_id = org_id_param AND cameras.deleted_at IS NULL

        UNION ALL

        -- Shared cameras
        SELECT * from shared_cameras

        UNION ALL

        -- Commercial cameras
        -- DEV-1512: Added LEFT JOIN to org_meta on source org to filter by aggregated_data_sharing
        SELECT kits.id,
               'Commercial'::varchar as name,
               kits.kit_type,
               kits.org_id,
               true as is_commercial,
               false as is_shared,
               scope
        FROM public.kits
                 JOIN public.orgs ON orgs.id = kits.org_id
                 LEFT JOIN public.org_meta AS source_org_meta ON source_org_meta.id = kits.org_id
        WHERE kits.org_id != org_id_param
          AND orgs.type != 4
          AND org_commercial_data_feed_variable = true
          AND kits.id NOT IN (SELECT shared_cameras.id FROM shared_cameras)
          AND coalesce(source_org_meta.properties->>'aggregated_data_sharing', 'true') != 'false';


END;
$$;


--
-- Name: org_shared_cameras(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.org_shared_cameras(org_id_param bigint) RETURNS SETOF overwatch.user_camera
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

BEGIN
    RETURN QUERY

         select distinct kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               true as is_shared
            from public.kits
                join overwatch.cameras on cameras.id = kits.id
                join overwatch.shared on shared_id = kits.org_id and shared_type ='org_cameras'
            where shared_with_id = org_id_param and shared_with_type = 'org'
              and (shared.expires_at is null or shared.expires_at > now())
              and status_id = 1
              and cameras.deleted_at is null
             and shared.deleted_at is null
union all

         select distinct kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               true as is_shared
            from public.kits
                join overwatch.cameras on cameras.id = kits.id
                join overwatch.locations on locations.id = cameras.location_id
                join overwatch.shared on shared_id = locations.site_id and shared_type ='site_cameras'
            where shared_with_id = org_id_param and shared_with_type = 'org'
              and (shared.expires_at is null or shared.expires_at > now())
              and status_id = 1
              and cameras.deleted_at is null
              and shared.deleted_at is null ;




END; $$;


--
-- Name: process_all_orgs(); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.process_all_orgs() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    org_record RECORD;
    drop_view_sql TEXT;
    view_name TEXT;

BEGIN
    FOR org_record IN (SELECT id,name FROM public.orgs where type not in (1,2,3) ORDER BY id) LOOP
            -- Perform operations for each organization here
            RAISE NOTICE 'Processing org: % (ID: %)', org_record.name, org_record.id;

            view_name := 'org_' || org_record.id || '_cameras';
            -- DROP the org_1_cameras view for this org
            IF EXISTS (
                SELECT 1 FROM pg_matviews
                WHERE schemaname = 'overwatch' AND matviewname = view_name
            )THEN
                drop_view_sql := format('DROP MATERIALIZED VIEW IF EXISTS overwatch.%I', view_name);
                RAISE NOTICE 'Dropping view %', drop_view_sql;
                EXECUTE drop_view_sql;
            END IF;

            PERFORM overwatch.manage_org_cameras_view(org_record.id);
            RAISE NOTICE 'View % created.', view_name;

        END LOOP;
END;
$$;


--
-- Name: update_camera_status(); Type: PROCEDURE; Schema: overwatch; Owner: -
--

CREATE PROCEDURE overwatch.update_camera_status()
    LANGUAGE plpgsql
    AS $$
begin
    WITH dataset AS (SELECT cameras.id,
                        cameras.deployment_type,
                        cameras.last_scan_date,
                        CASE
                            WHEN cameras.last_scan_date IS NULL THEN 2
                            ELSE
                                CASE
                                    WHEN cameras.deployment_type = 0 AND
                                         cameras.last_scan_date < (now() - '7 days'::interval) THEN 2
                                    WHEN cameras.deployment_type = 1 AND
                                         cameras.last_scan_date < (now() - '45 days'::interval) THEN 2

                                    WHEN cameras.last_scan_date < (now() - '06:00:00'::interval) THEN 2
                                    ELSE 1
                                    END
                            END AS camera_status,
                            cameras.status_notification
                 FROM overwatch.cameras
                          JOIN kits ON cameras.id = kits.id
                          JOIN orgs ON orgs.id = kits.org_id
                 WHERE cameras.deleted_at IS NULL
                   AND cameras.last_scan_date IS NOT NULL
                   and cameras.disposition = 1
                   AND kits.kit_type <> 1
                   AND (orgs.type <> ALL (ARRAY [1, 2, 3]))
                   AND (kits.org_id <> ALL (ARRAY [1, 3, 281531]))),
status_data as (SELECT id,
       camera_status,
    CASE
           WHEN camera_status = 2 THEN status_notification
           END AS status_notification
FROM dataset)
update overwatch.cameras
    set status_notification = status_data.status_notification,
        status = status_data.camera_status
    from status_data
    where status_data.id = overwatch.cameras.id;
end;
$$;


--
-- Name: user_cameras(bigint, boolean, boolean); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.user_cameras(user_id_param bigint, commercial boolean DEFAULT true, owned boolean DEFAULT true) RETURNS SETOF overwatch.user_camera
    LANGUAGE plpgsql IMMUTABLE COST 10 PARALLEL SAFE
    AS $$

    DECLARE
        org_id_variable BIGINT;
        org_type_variable INT;
        org_commercial_data_feed_variable BOOLEAN;

BEGIN
        select orgs.type,
               orgs.id as id,
                 CASE WHEN org_meta.properties->>'commercial_data_feed' = 'true' THEN true ELSE false END
        from public.orgs
         left join public.org_meta on orgs.id = org_meta.id
         join overwatch.users on users.org_id = orgs.id
         where users.id = user_id_param into org_type_variable, org_id_variable, org_commercial_data_feed_variable;


        IF commercial = TRUE and owned = TRUE THEN

    RETURN QUERY
        with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_variable))

        select kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               false as is_shared
        from public.kits
            join overwatch.cameras on cameras.id = kits.id
            join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_variable and locations.site_id in (select id from overwatch.user_sites(user_id_param))

            UNION ALL
                select * from org_shared_cameras
            UNION ALL

            select kits.id,
               'Commercial'::varchar as name,
               kits.kit_type,
               kits.org_id,
               true as is_commercial,
               false as is_shared
            from public.kits
            join public.orgs on orgs.id = kits.org_id
            where org_id != org_id_variable
              and orgs.type != 4
              and org_commercial_data_feed_variable = true
              and kits.id not in (select id from org_shared_cameras)
    ;

    ELSEIF commercial = TRUE AND owned = FALSE THEN
        RETURN QUERY
            with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_variable))
            select kits.id,
               'Commercial'::varchar as name,
               kits.kit_type,
               kits.org_id,
               true as is_commercial,
               false as is_shared
            from public.kits
            join orgs as po on po.id = kits.org_id
            where org_id != org_id_variable and po.type != 4 and org_commercial_data_feed_variable = true
           and kits.id not in (select id from org_shared_cameras)
        ;


    ELSEIF commercial = FALSE AND owned = TRUE THEN
        RETURN QUERY
            select kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               false as is_shared
        from public.kits
            join overwatch.cameras on cameras.id = kits.id
            join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_variable and locations.site_id in (select id from overwatch.user_sites(user_id_param))
        UNION ALL
            select * from overwatch.org_shared_cameras(org_id_variable);
        END IF;


END; $$;


--
-- Name: user_cameras2(bigint, boolean, boolean); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.user_cameras2(user_id_param bigint, commercial_param boolean DEFAULT true, owned_param boolean DEFAULT true) RETURNS SETOF overwatch.user_camera
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

    DECLARE
        org_id_variable INT;

BEGIN
        select org_id from overwatch.users where id = user_id_param into org_id_variable;

    RETURN QUERY
        with allowed_sites as (select id from overwatch.user_sites(user_id_param::integer))

            select oc.* from overwatch.org_cameras(org_id_variable::bigint, commercial_param, owned_param) oc
            left join overwatch.cameras on cameras.id = oc.id
            left join overwatch.locations on locations.id = cameras.location_id
       where
           CASE WHEN oc.is_commercial or oc.is_shared THEN true
               ELSE  locations.site_id in (select id from allowed_sites) END;


END; $$;


