--
-- Name: integrations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.integrations (
    id integer NOT NULL,
    name character varying(64) NOT NULL,
    status character varying(16) DEFAULT 'run'::character varying NOT NULL,
    batch_id bigint,
    mapping_id integer DEFAULT 1 NOT NULL,
    mapping_type character varying(64)
);


--
-- Name: integrations_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.integrations_view AS
 SELECT id,
    name,
    status,
    batch_id,
    mapping_id,
    mapping_type,
    org_id,
    shared
   FROM ( SELECT integrations.id,
            integrations.name,
            integrations.status,
            integrations.batch_id,
            integrations.mapping_id,
            integrations.mapping_type,
            integrations.mapping_id AS org_id,
            false AS shared
           FROM public.integrations
          WHERE (((integrations.mapping_type)::text = 'org'::text) AND (integrations.mapping_id <> 1))
        UNION ALL
         SELECT integrations.id,
            integrations.name,
            integrations.status,
            integrations.batch_id,
            integrations.mapping_id,
            integrations.mapping_type,
            users.org_id,
            false AS shared
           FROM (public.integrations
             JOIN overwatch.users ON ((users.id = integrations.mapping_id)))
          WHERE (((integrations.mapping_type)::text = 'user'::text) AND (users.deleted_at IS NULL))
        UNION ALL
         SELECT integrations.id,
            integrations.name,
            integrations.status,
            integrations.batch_id,
            integrations.mapping_id,
            integrations.mapping_type,
            territories.org_id,
            false AS shared
           FROM ((public.integrations
             JOIN overwatch.sites ON (((sites.id = integrations.mapping_id) AND ((integrations.mapping_type)::text = 'sites'::text))))
             JOIN overwatch.territories ON ((territories.id = sites.territory_id)))
          WHERE ((sites.deleted_at IS NULL) AND (territories.deleted_at IS NULL))
        UNION ALL
         SELECT integrations.id,
            integrations.name,
            integrations.status,
            integrations.batch_id,
            integrations.mapping_id,
            integrations.mapping_type,
            shared.shared_with_id AS org_id,
            true AS shared
           FROM (overwatch.shared
             JOIN public.integrations ON ((shared.shared_id = integrations.id)))
          WHERE (((shared.shared_with_type)::text = 'org'::text) AND ((shared.shared_type)::text = 'integrations'::text) AND (shared.deleted_at IS NULL) AND ((shared.expires_at > now()) OR (shared.expires_at IS NULL)))) hotlists;


--
-- Name: user_hotlists(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.user_hotlists(user_id_param bigint) RETURNS SETOF public.integrations_view
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$


BEGIN
        RETURN QUERY
        with user_sites as materialized (
    select * from overwatch.user_sites(user_id_param)
),
            user_info as materialized (
    select id,org_id from overwatch.users where id = user_id_param
            ),
    shared_with_user as materialized (
        select * from overwatch.shared where shared_with_id = user_id_param
                                       and shared_with_type = 'user'
                                       and shared.shared_type = 'integrations'
                                       and shared.shared_with_id = user_id_param
                                       and shared.deleted_at is null
                                       and (expires_at > now() or shared.expires_at is null)
    )
select iv.*
    from public.integrations_view as iv
    where iv.org_id = (select org_id from user_info)
       and (
        (mapping_type = 'org' and mapping_id = (select org_id from user_info))
            or
        (mapping_type = 'org' and shared = false)
            or
        (iv.shared = false and iv.mapping_type = 'sites' and iv.mapping_id in (select id from user_sites))
            or
        (iv.shared and iv.org_id = (select org_id from user_info))
            or
        (iv.shared = false and iv.mapping_type = 'territories' and mapping_id in (select territory_id from user_sites))
            or
        (iv.shared = false and iv.mapping_type = 'user' and
         (exists(select 1 from shared_with_user where shared_with_user.shared_id = iv.id) or iv.mapping_id = user_id_param))
        )
;

END; $$;


--
-- Name: user_sites(bigint); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.user_sites(user_id_param bigint) RETURNS SETOF overwatch.sites
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

DECLARE
    org_id_variable INT;

BEGIN

    select org_id from overwatch.users where id = user_id_param into org_id_variable;

    IF EXISTS (select 1
                                from overwatch.sites
                                         join overwatch.territories on overwatch.territories.id = sites.territory_id
                                         join overwatch.shared on shared_id = sites.id and shared_type = 'sites'
                                where shared_with_id = user_id_param
                                  and org_id = org_id_variable
                                  and shared.deleted_at is null
                                  and territories.deleted_at is null
                                    and sites.deleted_at is null
                                  and shared_with_type = 'user') THEN
        RETURN QUERY
           select sites.*
                                from overwatch.sites
                                         join overwatch.territories on overwatch.territories.id = sites.territory_id
                                         join overwatch.shared on shared_id = sites.id and shared_type = 'sites'
                                where
                                    shared.deleted_at is null
                                and territories.deleted_at is null
                                and sites.deleted_at is null
                                and shared_with_id = user_id_param
                                and shared_with_type = 'user';
    ELSE
        RETURN QUERY
            select sites.*
                              from overwatch.sites
                                       join overwatch.territories on overwatch.territories.id = sites.territory_id
                              where org_id = org_id_variable and sites.deleted_at is null and territories.deleted_at is null;
    END IF;

END;
$$;


--
-- Name: validate_warranty_date(jsonb); Type: FUNCTION; Schema: overwatch; Owner: -
--

CREATE FUNCTION overwatch.validate_warranty_date(properties jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    -- If warranty_expiration_date doesn't exist or is null, allow it
    IF properties->'warranty_expiration_date' IS NULL THEN
        RETURN TRUE;
    END IF;

    -- Check if it matches YYYY-MM-DD format
    IF properties->>'warranty_expiration_date' !~ '^\d{4}-\d{2}-\d{2}$' THEN
        RETURN FALSE;
    END IF;

    -- Check if it's a valid date
    BEGIN
        PERFORM (properties->>'warranty_expiration_date')::date;
        RETURN TRUE;
    EXCEPTION WHEN OTHERS THEN
        RETURN FALSE;
    END;
END;
$_$;


--
-- Name: upsert_recoveries_for_days(integer); Type: FUNCTION; Schema: platform; Owner: -
--

CREATE FUNCTION platform.upsert_recoveries_for_days(days_ago integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN

    WITH recoveries_data AS (
        SELECT hotlist.id,
               hotlist.integration_id,
               hotlist.remote_order_id,
               hotlist.status,
               hotlist.org_id,
               hotlist.client_org_id,
               hotlist.lienholder_org_id,
               hotlist.order_type,
               hotlist.is_staged,
               hotlist.plate,
               hotlist.us_state,
               hotlist.vin,
               hotlist.vehicle_year,
               hotlist.vehicle_make,
               hotlist.vehicle_model,
               hotlist.lookback_days,
               hotlist.created_at,
               hotlist.updated_at,
               recovery_address.address_id,
               recovery_address.house_number,
               recovery_address.road,
               recovery_address.city,
               recovery_address.state,
               recovery_address.postcode,
               recovery_address.geo,
               hotlist_meta.repo_date
        FROM public.hotlist
                 LEFT JOIN LATERAL (
            SELECT id,
                   row_number,
                   address_id,
                   geo,
                   road,
                   house_number,
                   state,
                   city,
                   postcode
            FROM (
                     SELECT hotlist_address.hotlist_id AS id,
                            row_number() OVER (PARTITION BY hotlist_address.hotlist_id ORDER BY hotlist_address.address_id) AS row_number,
                            a.id AS address_id,
                            a.geo,
                            a.road,
                            a.house_number,
                            a.state,
                            a.city,
                            a.postcode
                     FROM public.hotlist_address
                              JOIN address a ON a.id = hotlist_address.address_id
                     WHERE a.type_id = 2
                       AND hotlist_address.hotlist_id = hotlist.id
                 ) t
            WHERE row_number = 1
            ) AS recovery_address ON true
                 JOIN public.hotlist_meta ON hotlist_meta.hotlist_id = hotlist.id
        WHERE hotlist.status = 3
          AND hotlist_meta.repo_date IS NOT NULL
          AND hotlist_meta.repo_date >= now() - interval '6 day' * days_ago
    )
    INSERT INTO platform.recoveries
    SELECT * FROM recoveries_data
    ON CONFLICT (id) DO UPDATE SET
                                   integration_id = EXCLUDED.integration_id,
                                   remote_order_id = EXCLUDED.remote_order_id,
                                   status = EXCLUDED.status,
                                   org_id = EXCLUDED.org_id,
                                   client_org_id = EXCLUDED.client_org_id,
                                   lienholder_org_id = EXCLUDED.lienholder_org_id,
                                   order_type = EXCLUDED.order_type,
                                   is_staged = EXCLUDED.is_staged,
                                   plate = EXCLUDED.plate,
                                   us_state = EXCLUDED.us_state,
                                   vin = EXCLUDED.vin,
                                   vehicle_year = EXCLUDED.vehicle_year,
                                   vehicle_make = EXCLUDED.vehicle_make,
                                   vehicle_model = EXCLUDED.vehicle_model,
                                   lookback_days = EXCLUDED.lookback_days,
                                   created_at = EXCLUDED.created_at,
                                   updated_at = EXCLUDED.updated_at,
                                   address_id = EXCLUDED.address_id,
                                   house_number = EXCLUDED.house_number,
                                   road = EXCLUDED.road,
                                   city = EXCLUDED.city,
                                   state = EXCLUDED.state,
                                   postcode = EXCLUDED.postcode,
                                   geo = EXCLUDED.geo;

END;
$$;


--
-- Name: add_daytime_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_daytime_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    local_timezone TEXT := 'UTC';
    is_daytime_value BOOLEAN;
BEGIN
    -- Get the timezone for the scan's location
    SELECT tzid INTO local_timezone
    FROM timezones
    WHERE ST_Within(NEW.geo, timezones.geom) = true
    LIMIT 1;

    -- Determine if scan is during daytime hours (6am to 8pm)
    is_daytime_value := EXTRACT(HOUR FROM NEW.scanned_at AT TIME ZONE 'UTC' AT TIME ZONE local_timezone) BETWEEN 6 AND 19;

    -- Insert or update the metadata
    INSERT INTO scans_metadata (scan_id, meta)
    VALUES (
               NEW.id,
               jsonb_build_object('is_daytime', CASE WHEN is_daytime_value THEN true ELSE false END)
           )
    ON CONFLICT (scan_id)
        DO UPDATE SET
        meta = scans_metadata.meta || jsonb_build_object('is_daytime',
                                                         CASE WHEN is_daytime_value THEN true ELSE false END);

    RETURN NEW;
END;
$$;


--
-- Name: add_metric(character varying, double precision, public.datadog_metric_type); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_metric(metric_name character varying, metric_value double precision, metric_type public.datadog_metric_type DEFAULT 'gauge'::public.datadog_metric_type) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Your logic to handle the metric goes here
  -- For example, you might want to insert the metric into a table
  INSERT INTO public.datadog_metrics (type, name, value, created_at)
  VALUES (metric_type, metric_name,metric_value, NOW());
END;
$$;


--
-- Name: aggregate_scan_count(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.aggregate_scan_count() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
start_of_hour TIMESTAMP;
end_of_hour TIMESTAMP;
        BEGIN

        IF NEW.is_visible THEN
			insert into aggregate_scan_count_h (timeblock, kit_id, scan_count) VALUES (FLOOR((extract(epoch from date_trunc('second',NEW.scanned_at::timestamp)))/3600), NEW.kit_id, 1)
			ON CONFLICT ON CONSTRAINT aggregate_scan_count_h_unq DO UPDATE SET scan_count=aggregate_scan_count_h.scan_count+1 WHERE aggregate_scan_count_h.kit_id=NEW.kit_id AND aggregate_scan_count_h.timeblock=FLOOR((extract(epoch from date_trunc('second',NEW.scanned_at::timestamp)))/3600)
			;
        END IF;
		start_of_hour := date_trunc('hour', NEW.scanned_at);
        end_of_hour := start_of_hour + INTERVAL '1 hour' - INTERVAL '1 second';

		IF NEW.is_visible AND NOT EXISTS (SELECT id FROM scans WHERE ocr=NEW.ocr AND is_visible AND kit_id=NEW.kit_id AND FLOOR((extract(epoch from date_trunc('second',scanned_at::timestamp)))/3600) = FLOOR((extract(epoch from date_trunc('second',NEW.scanned_at::timestamp)))/3600) AND scanned_at BETWEEN start_of_hour AND end_of_hour AND id<>NEW.id LIMIT 1) THEN
        	insert into aggregate_scan_count_unq_h (timeblock, kit_id, scan_count) VALUES (FLOOR((extract(epoch from date_trunc('second',NEW.scanned_at::timestamp)))/3600), NEW.kit_id, 1)
			ON CONFLICT ON CONSTRAINT aggregate_scan_count_unq_h_unq DO UPDATE SET scan_count=aggregate_scan_count_unq_h.scan_count+1 WHERE aggregate_scan_count_unq_h.kit_id=NEW.kit_id AND aggregate_scan_count_unq_h.timeblock=FLOOR((extract(epoch from date_trunc('second',NEW.scanned_at::timestamp)))/3600)
			;
		END IF;
		RETURN NEW;
        END;
$$;


--
-- Name: alerter_hit_users(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.alerter_hit_users(hit_id_param bigint) RETURNS SETOF overwatch.hit_user
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
BEGIN
    RETURN QUERY
     WITH
        hit_data AS (
            SELECT hits.id, integration_id
            FROM public.hits
            JOIN public.hotlist ON hotlist.id = hits.hotlist_id
            WHERE hits.id = hit_id_param
        ),
        settings_matching_hit AS (
            SELECT *
            FROM overwatch.alert_settings
            JOIN LATERAL (SELECT integration_id FROM hit_data) integration ON TRUE
            WHERE (integration.integration_id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings->'hotlists')::text)))
              AND alert_settings.type = 1
              AND alertable_type in ('integrations', 'user')
              AND settings->'notifications'->'alerter' IS NOT NULL
              AND settings->'notifications'->'alerter' != '[]'::jsonb
              AND alert_settings.deleted_at IS NULL
        ),
        alerter_users AS (
            SELECT DISTINCT
                jsonb_array_elements_text(settings_matching_hit.settings->'notifications'->'alerter')::bigint AS user_id, settings_matching_hit.id as setting_id
            FROM settings_matching_hit
        )
    SELECT
        DISTINCT users.id AS user_id,
        users.org_id AS org_id,
        hits.id AS hit_id,
        uc.id::bigint AS camera_id,
        uc.name AS camera_name,
        uc.is_commercial,
        uc.is_shared
    FROM public.integrations_view iv
    JOIN public.hotlist ON hotlist.integration_id = iv.id
    JOIN public.hits ON hits.hotlist_id = hotlist.id
    JOIN public.scans ON hits.scan_id = scans.id
    JOIN overwatch.users ON overwatch.users.org_id = iv.org_id AND overwatch.users.deleted_at IS NULL
    JOIN alerter_users ON alerter_users.user_id = users.id
    JOIN overwatch.user_cameras2(users.id::bigint) uc ON scans.kit_id = uc.id
    JOIN settings_matching_hit ON alerter_users.setting_id = settings_matching_hit.id
    WHERE
        hits.hit_type = 'O'
        AND (
            (settings_matching_hit.settings->'cameras' IS NULL OR settings_matching_hit.settings->'cameras' = '[]'::jsonb)
            OR (
                uc.id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'cameras')::text))
                OR (
                    '-1'::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'cameras')::text))
                    AND uc.is_commercial = TRUE
                )
            )
        )
        AND (
            (settings_matching_hit.settings->'geozones' IS NULL OR settings_matching_hit.settings->'geozones' = '[]'::jsonb)
            OR (
                EXISTS (
                    SELECT 1
                    FROM overwatch.geo_zones
                    WHERE geo_zones.id::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'geozones')::text))
                    AND public.st_within(scans.geo, geo_zones.geom)
                )
            )
        )
        AND (
            (settings_matching_hit.settings->'states' IS NULL OR settings_matching_hit.settings->'states' = '[]'::jsonb)
            OR (
                hotlist.us_state::varchar = ANY (ARRAY(SELECT jsonb_array_elements_text(settings_matching_hit.settings->'states')::text))
            )
        )
        AND hits.id = hit_id_param;
END;
$$;


--
-- Name: copy_to_new_scans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_to_new_scans() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
		INSERT INTO new_scans (
			id,
			ocr,
			us_state,
			geo,
			kit_id,
			is_visible,
			scanned_at,
			created_at,
			camera_name,
			guid,
			meta
		)
		VALUES (
			NEW.id,
			NEW.ocr,
			NEW.us_state,
			NEW.geo,
			NEW.kit_id,
			NEW.is_visible,
			NEW.scanned_at,
			NEW.created_at,
			NEW.camera_name,
			NEW.guid,
			NULL::jsonb
		);
		RETURN NEW;
        END;
$$;


--
-- Name: delete_overwatch_camera_func(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_overwatch_camera_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
   SELECT deleted_at INTO OLD.deleted_at FROM overwatch.cameras WHERE id = OLD.id;
   IF OLD.deleted_at IS NULL THEN
      UPDATE overwatch.cameras SET deleted_at = now() WHERE id = OLD.id;
   -- ELSE
   --   DELETE from overwatch.cameras WHERE id = OLD.id;
   END IF;
   RETURN OLD;
END
$$;


--
-- Name: dispatch_hits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_hits() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
    BEGIN
    INSERT INTO procrastinate_jobs (queue_name, task_name, lock, queueing_lock, args, status, scheduled_at, attempts) VALUES
    (
        'hits',
        'hits:tasks.hits.dispatch_hits',
        null,
        null,
        CONCAT('{"hit_id":',NEW.id, '}')::json,
        'todo',
        null,
        0
    );
    RETURN NEW;
    END;
    $$;


--
-- Name: dispatch_scans(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispatch_scans() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
	DECLARE
	  kit_record kits%ROWTYPE;
	  -- org_record orgs%ROWTYPE;
    BEGIN
	IF NEW.is_visible THEN
		SELECT * INTO kit_record FROM kits WHERE id = NEW.kit_id;
		-- SELECT * INTO org_record FROM orgs WHERE id = kit_record.org_id;

		IF (EXISTS(select id FROM org_data_export_scans WHERE scan_id=NEW.id AND scan_scanned_at = NEW.scanned_at)) OR (kit_record.org_id IN (
		    410964, -- Mississippi Highway Patrol (DPS)
		    -- 446091, -- Ridgeland Police Department
		    -- 382648, -- Rankin County Sheriff's Office
		    -- 445541, -- Brandon Police Department
		    -- 449631, -- Reservoir Police Department
		    420081, -- Pearl Police Department
		    441544, -- Clinton Police Department
		    445644, -- Oxford Police Department
		    454545, -- Lincoln Sheriff Office
		    -- 445550, -- Byram Police Department
		    -- 440979, -- Madison County Sheriff's Office
		    445500, -- Biloxi Police Department
		    -- 384144, -- Flowood PD
		    -- 420084, -- Madison Police Department
			407817, -- Cityplace Heights
			446004, -- Securix
			429647, -- Community Boss
			3,      -- InsightLPR Law Enforcement
			393241, -- Miami Gardens Police Department
			379901, -- Vicksburg PD
			-- 386247, -- Richland PD
			384147, -- Harrison County SO
			388153, -- DeSoto Sheriffs Office
			366924, -- Louisiana State Police
            516882, -- Fayette County Sheriff's Department
            440066, -- Fort Morgan Police Department
		    514963, -- DEA - National License Plate Reader Program
			418749, -- Forrest County SO
            460813, -- Dallas PD
			1143, -- RELENTLESS REPO (Ohio)
		    521236,  -- East Baton Rouge,
		    618078  -- Tupelo Police Department
	)) THEN
			INSERT INTO procrastinate_jobs (queue_name, task_name, lock, queueing_lock, args, status, scheduled_at, attempts) VALUES
			(
				'scans',
				'scans:tasks.scans.dispatch_scans',
				null,
				null,
				json_build_object('scan_id',NEW.id,'scanned_at',NEW.scanned_at),
				'todo',
				null,
				0
			);
		END IF;
	END IF;
    RETURN NEW;
    END;

$$;


--
-- Name: duplicate_nicb_as_ow(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.duplicate_nicb_as_ow() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

-- If we are adding a staging historical AND it's for NICB, then dupe an overwatch hit for them since OW doesn't NORMALLY do historicals (only lives)
IF NEW.hit_type='Z' AND EXISTS (SELECT 1 FROM hotlist WHERE integration_id=5 AND hotlist.id = NEW.hotlist_id)
THEN
	INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (NEW.hotlist_id , NEW.scan_id, 'O', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
END IF;

RETURN NEW;
END;
$$;


--
-- Name: enqueue_closes(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_closes() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
		DECLARE temprow RECORD;
        BEGIN
		-- This will ONLY enqueue CLOSES IF we have a HIT (not an Overwatch hit) for this same VIN !
        IF NEW.status != 1 AND NEW.status != 99 AND NEW.status != 88 AND NEW.status<>OLD.status AND NEW.vin is not null AND NEW.vin != '' AND EXISTS (SELECT 1 from hits JOIN hotlist ON (hotlist.id = hits.hotlist_id) WHERE hotlist.vin = NEW.vin AND hit_type<>'O') THEN
            INSERT INTO procrastinate_jobs (queue_name, task_name, lock, queueing_lock, args, status, scheduled_at, attempts) VALUES
            (
                'closes',
                'closes:tasks.closes.handle_close',
                null,
                null,
                CONCAT('{"hotlist_id":', NEW.id, '}')::json,
                'todo',
                null,
                0
            );
        END IF;

		-- if the order closes and we previously had a L/S hit, alert the agent that they should have picked up the car
		-- maybe it was moving or not available for repo, but they should verify. Otherwise, get the account back from lender (assuming it's still available)
		IF NEW.status != 1 AND NEW.status != 3 AND NEW.status<>OLD.status AND EXISTS (SELECT 1 from hits WHERE hotlist_id = NEW.id AND hit_type IN ('L','S')) AND NEW.integration_id<>5 THEN
       		FOR temprow IN
          		SELECT hits.scan_id,hits.kit_id from hits WHERE hotlist_id = NEW.id AND hit_type IN ('L','S')
        	LOOP
          		INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (NEW.id , temprow.scan_id, 'F', temprow.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
        	END LOOP;
        END IF;

		RETURN NEW;
        END;

$$;


--
-- Name: enqueue_repos(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_repos() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
        BEGIN
        IF NEW.status = 3 AND NEW.org_id IN (SELECT id from orgs WHERE rdn_api_key != '' and (enable_genetech_hotlist OR enable_matrix_hotlist)) THEN
            INSERT INTO procrastinate_jobs (queue_name, task_name, lock, queueing_lock, args, status, scheduled_at, attempts) VALUES
            (
                'repos',
                'repos:tasks.repos.handle_repo',
                null,
                null,
                CONCAT('{"hotlist_id":', NEW.id, '}')::json,
                'todo',
                null,
                0
            );
        END IF;
        RETURN NEW;
        END;

$$;


--
-- Name: find_historicals(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_historicals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        temprow RECORD;
    BEGIN

    -- new open direct assignments
    IF (NEW.status != COALESCE(OLD.status,0) OR NEW.plate != COALESCE(OLD.plate,'') OR NEW.us_state != COALESCE(OLD.us_state,'')) AND NEW.plate<>'' AND NEW.status IN (1) AND NEW.order_type IN (1,3,88) AND NOT NEW.is_staged AND NEW.lookback_days>0 AND NOT EXISTS (select * from blacklist_plates where plate=NEW.plate) THEN
        FOR temprow IN
          SELECT s.id,s.kit_id FROM scans s JOIN kits k ON (k.id = s.kit_id) JOIN orgs o ON (o.id = k.org_id) WHERE is_visible AND ocr=NEW.plate AND o.id = NEW.org_id AND s.scanned_at>=NOW()::DATE - NEW.lookback_days
        LOOP
          INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (NEW.id , temprow.id, 'H', temprow.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
        END LOOP;
    END IF;

-- 	RAISE NOTICE 'OLD.status is currently %', COALESCE(OLD.status,0);
-- 	RAISE NOTICE 'NEW.status is currently %', NEW.status;
    -- new open staged assignments
    IF (NEW.status != COALESCE(OLD.status,0) OR NEW.plate != COALESCE(OLD.plate,'') OR NEW.us_state != COALESCE(OLD.us_state,'') OR NEW.is_staged != COALESCE(OLD.is_staged,FALSE) OR NEW.updated_at != COALESCE(OLD.updated_at,NOW()) ) AND NEW.plate<>'' AND NEW.status IN (1) AND NEW.order_type IN (1,3,88) AND NEW.is_staged AND NEW.lookback_days>0 AND NOT EXISTS (select * from blacklist_plates where plate=NEW.plate) THEN
        FOR temprow IN
          SELECT s.id,s.kit_id
		  FROM scans s
		  JOIN kits ON (kits.id = s.kit_id)
		  JOIN orgs hotlist_org ON (NEW.org_id = hotlist_org.id) -- hotlist's org
		  LEFT JOIN approval_list ON (staging_org_id = NEW.org_id AND agent_org_id = kits.org_id)
		  LEFT JOIN hits ON (hits.hotlist_id = NEW.id AND hits.scan_id = s.id AND hits.hit_type IN ('S', 'Z'))
		  WHERE
		  is_visible AND ocr=NEW.plate AND s.scanned_at>=NOW()::DATE - NEW.lookback_days AND hits.id IS NULL
		  AND NEW.integration_id NOT IN (105,137,138) -- TitleMax doesnt want AAs for the initial roll-out
		  AND
		  ((approval_list.id IS NULL AND hotlist_org.silent_hit_generation) OR approval_list.id IS NOT NULL)
        LOOP
          INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (NEW.id , temprow.id, 'Z', temprow.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
        END LOOP;
    END IF;

    RETURN NEW;
    END;

$$;


--
-- Name: find_hits(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.find_hits() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
    temprow RECORD;
    had_staging_hit BOOLEAN;
    had_live_hit BOOLEAN;
BEGIN
    had_staging_hit = False;
    had_live_hit = False;
    -- only perform the hit detection IF we don't have an exact duplicate of that scan (based on ocr/kit/scanned_at/geo)
-- this assumes the first insert of the scan DID cause a hit
    IF NOT EXISTS (SELECT 1 FROM scans WHERE ocr=NEW.ocr and kit_id=NEW.kit_id AND scanned_at=NEW.scanned_at AND id<>NEW.id) AND NEW.scanned_at>NOW()-INTERVAL '7 DAY'
    THEN
        -- this matches hits for scanners' org
        -- !!! IMPORTANT !!! This is only for Repo Companies. Others are via Overwatch (hit_type=O), below
        FOR temprow IN
            SELECT h.id FROM hotlist h JOIN orgs o ON (o.id = h.org_id) JOIN kits k ON (k.org_id = o.id AND k.id = NEW.kit_id) WHERE h.plate=NEW.ocr AND h.status IN (1) AND h.order_type IN (1,3,88) AND NEW.is_visible AND o.type=1
            LOOP
                INSERT INTO hits (hotlist_id,scan_id, hit_type, kit_id) VALUES (temprow.id , NEW.id, 'L', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
                had_live_hit = True;
            END LOOP;

        -- only perform the hit detection IF we don't have an exact duplicate of that scan (based on ocr/kit/scanned_at/geo)
        -- this assumes the first insert of the scan DID cause a hit
        -- check for staged hotlist items
        FOR temprow IN
            SELECT h.id FROM hotlist h
                                 JOIN kits ON (kits.id = NEW.kit_id)
                                 JOIN orgs hotlist_org ON (h.org_id = hotlist_org.id) -- hotlist's org
                                 LEFT JOIN approval_list ON (staging_org_id = h.org_id AND agent_org_id = kits.org_id)
            WHERE
                NEW.is_visible AND h.is_staged
              AND h.plate=NEW.ocr AND h.status IN (1) AND h.order_type IN (1,3,88)
              -- either we dont have an approval list but we are a silent hit generator OR scanner is approved
              AND ((approval_list.id IS NULL AND hotlist_org.silent_hit_generation) OR approval_list.id IS NOT NULL)
            LOOP
                INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id , NEW.id, 'S', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
                had_staging_hit = True;
            END LOOP;

        -- check for OVERWATCH hotlist items
        FOR temprow IN
            SELECT h.id FROM hotlist h
                                 JOIN integrations ON (h.integration_id = integrations.id AND integrations.mapping_id NOT IN (1) AND integrations.mapping_id IS NOT NULL AND integrations.status IN ('active', 'run') )
                                 JOIN kits ON (kits.id = NEW.kit_id)
                                 JOIN orgs scanners_org ON (kits.org_id = scanners_org.id) -- scanner's org
            WHERE
                NEW.is_visible
              AND h.plate=NEW.ocr
              AND h.status IN (1)
              AND h.integration_id != 1
              AND ( (h.integration_id=2 AND scanners_org.id=424540) OR (h.integration_id != 2) ) --TRX testing against LS hotlist
            LOOP
                INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id , NEW.id, 'O', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
            END LOOP;

        IF NOT had_staging_hit THEN
            -- check for "missed opportunity" hits which are hits against a direct order that's no longer open with the insight
            -- agent, but is still open (non staged) with another agent and the insights agent hotlist was updated within 90 days
            FOR temprow IN
                SELECT h.id
                FROM hotlist h -- the org who scanned it
                         JOIN hotlist h2 ON (h.vin = h2.vin and h.id<>h2.id and not h2.is_staged AND h2.status=1 and h2.org_id <> h.org_id AND h2.integration_id=1) --any other RDN orders for same VIN
                         LEFT JOIN hotlist h3 ON (h.vin = h3.vin and h3.org_id = h.org_id and h3.status=1) -- ensuring that the org doesnt have a second open order for the same vin
                         JOIN orgs o ON (o.id = h.org_id)
                         JOIN kits k ON (k.org_id = o.id AND k.id = NEW.kit_id)
                WHERE
                    h.plate=NEW.ocr --plates match
                  AND h.status IN (2,5) -- closed or on hold
                  AND h.order_type IN (1,3,88)
                  AND NEW.is_visible -- valid scan
                  AND h2.id is not NULL -- there is another open order
                  AND h.updated_at>=NOW() - INTERVAL '90 days' --touched within the last 90d
                  AND h3.id is null -- the scanning org doesnt have the same vin open with itself
                LIMIT 1 -- limit one because we dont need the same ID multiple times
                LOOP
                    INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id , NEW.id, 'M', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
                END LOOP;
        END IF;

        -- LS "missed opportunities": the idea here is to notify LS (via 'A' hit) that a previously open staged assignment was just hit
        -- as long as the agent or any other Insight agent doesnt currently have it open
        IF NOT had_live_hit THEN
            FOR temprow IN
                SELECT h.id -- LS's previously closed assignment ID
                FROM hotlist h -- LS's hotlist
                         JOIN hotlist h2 ON (h.vin = h2.vin and h.id<>h2.id AND h2.status=1 AND h2.integration_id IN (1,6,8,9,10,11,44,1482) AND h2.org_id<>165 and h2.org_id<>851 and h2.org_id<>6523) -- matching open VIN (staged or not)
                         JOIN orgs ON (h2.org_id = orgs.id AND NOT enable_genetech_hotlist) -- ensure that no InsightLPR agent has the open order
                         JOIN kits ON (kits.id = NEW.kit_id)
                         JOIN orgs the_scanning_org ON (kits.org_id = the_scanning_org.id AND the_scanning_org.type=1)
                         LEFT JOIN hotlist h3 ON (h.vin = h3.vin and h3.integration_id = 2 and h3.status=1) -- ensure LS doesn't have a second assignment open for same VIN
                         LEFT JOIN hotlist h4 ON (h.vin = h4.vin and h4.status=3 and h4.integration_id IN (1,6,8,9,10,11,44,1482) and h4.updated_at>=NOW() - INTERVAL '90 days')
                WHERE
                    h.plate = NEW.ocr -- plates match
                  AND h.us_state = NEW.us_state -- lets do this to cut down on extra crap
                  AND NEW.is_visible -- valid scan
                  AND h.integration_id = 2 -- is from LS
                  AND h.status = 77 -- is not open with LS any more (77 is "closed from LS\run.py")
                  AND h.updated_at>=NOW() - INTERVAL '90 days' -- but was updated in last 90d
                  AND h3.id IS NULL -- ensure LS doesn't have a second assignment open for same VIN
                  AND h4.id IS NULL -- ensure not other repos for this VIN; reason: there is a delay from agent repo to forwarders/staging and we dont need false positives
                LOOP
                    INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id , NEW.id, 'A', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
                END LOOP;
        END IF;

        -- check for WHITELIST violations (hit_type=W)
        -- fires when a kit scans a plate that is NOT in the whitelist for that kit's org
        -- only checks orgs that have whitelist entries (no whitelist = no W hits)
        -- excludes soft-deleted and expired whitelist records
        -- excludes entries where integration mapping_id = 1 or integration is not active
        -- us_state=NULL matches any state; specific us_state must match scan's us_state
        IF NEW.is_visible THEN
            FOR temprow IN
                SELECT wh.id
                FROM kits k
                JOIN hotlist_whitelist wh ON (wh.kit_id = k.id AND wh.deleted_at IS NULL)
                JOIN integrations wh_int ON (wh_int.id = wh.integration_id AND NOT (wh_int.mapping_type = 'org' AND wh_int.mapping_id = 1) AND wh_int.status IN ('active', 'run'))
                WHERE k.id = NEW.kit_id
                AND (wh.expires_at IS NULL OR wh.expires_at > NOW())
                AND NOT EXISTS (
                    SELECT 1 FROM hotlist_whitelist hwl
                    JOIN integrations hwl_int ON (hwl_int.id = hwl.integration_id AND NOT (hwl_int.mapping_type = 'org' AND hwl_int.mapping_id = 1) AND hwl_int.status IN ('active', 'run'))
                    WHERE hwl.org_id = k.org_id
                    AND hwl.plate = NEW.ocr
                    AND hwl.deleted_at IS NULL
                    AND (hwl.expires_at IS NULL OR hwl.expires_at > NOW())
                    AND (hwl.us_state IS NULL OR hwl.us_state = NEW.us_state)
                )
                LIMIT 1
            LOOP
                INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id, NEW.id, 'W', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
            END LOOP;
        END IF;

        -- check for GEOLOCATION alerts (hit_type=G)
        -- fires when a scan's location falls within a hotlist_geolocation polygon boundary
        -- scoped to the scanning kit, excludes soft-deleted and expired
        -- excludes where integration ( mapping_id = 1 and mapping_type = org )or integration is not active
        -- empty plate list = fires for any plate
        -- plate list present = fires only for matching plate+state
        IF NEW.is_visible THEN
            FOR temprow IN
                SELECT ga.id
                FROM hotlist_geolocation ga
                JOIN kits k ON (k.id = NEW.kit_id)
                JOIN integrations ga_int ON (ga_int.id = ga.integration_id AND NOT (ga_int.mapping_type = 'org' AND ga_int.mapping_id = 1) AND ga_int.status IN ('active', 'run'))
                WHERE ST_Within(NEW.geo, ga.boundary)
                AND ga.deleted_at IS NULL
                AND (ga.expires_at IS NULL OR ga.expires_at > NOW())
                AND (
                    -- No plates defined = fire for any plate
                    NOT EXISTS (
                        SELECT 1 FROM hotlist_geolocation_plates gap
                        WHERE gap.hotlist_geolocation_id = ga.id AND gap.deleted_at IS NULL
                    )
                    OR
                    -- Plate list defined = fire only for matching plate+state
                    EXISTS (
                        SELECT 1 FROM hotlist_geolocation_plates gap
                        WHERE gap.hotlist_geolocation_id = ga.id
                        AND gap.plate = NEW.ocr
                        AND gap.deleted_at IS NULL
                        AND (gap.us_state IS NULL OR gap.us_state = NEW.us_state)
                    )
                )
            LOOP
                INSERT INTO hits (hotlist_id, scan_id, hit_type, kit_id) VALUES (temprow.id, NEW.id, 'G', NEW.kit_id) ON CONFLICT(hotlist_id, scan_id, hit_type) DO NOTHING;
            END LOOP;
        END IF;


    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: get_license_plate_variants(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_license_plate_variants(input_text text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$
DECLARE
    char_mappings JSONB := '{
        "0": ["0", "O", "D", "Q"],
        "1": ["1", "I", "L"],
        "2": ["2", "Z"],
        "3": ["3", "8", "B"],
        "5": ["5", "S"],
        "6": ["6", "G"],
        "8": ["8", "3", "B"],
        "B": ["B", "8", "3"],
        "D": ["D", "0"],
        "G": ["G", "6"],
        "I": ["I", "1", "L"],
        "L": ["L", "I", "1"],
        "O": ["O", "0", "Q"],
        "Q": ["Q", "O", "0"],
        "S": ["S", "5"],
        "Z": ["Z", "2"]
    }';
    result TEXT[] := ARRAY[input_text];
    current_char TEXT;
    alternatives TEXT[];
    new_variants TEXT[];
    variant TEXT;
    alt TEXT;
    i INTEGER;
BEGIN
    FOR i IN 1..length(input_text) LOOP
            current_char := substring(input_text FROM i FOR 1);

            IF char_mappings ? current_char THEN
                alternatives := ARRAY(SELECT jsonb_array_elements_text(char_mappings->current_char));
                new_variants := ARRAY[]::TEXT[];

                FOREACH variant IN ARRAY result LOOP
                        FOREACH alt IN ARRAY alternatives LOOP
                                new_variants := array_append(new_variants,
                                                             overlay(variant PLACING alt FROM i FOR 1));
                            END LOOP;
                    END LOOP;

                result := new_variants;
            END IF;
        END LOOP;

    RETURN array(SELECT DISTINCT unnest(result));
END;
$$;


