--
-- Name: manage_org_cameras_view(bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_org_cameras_view(p_org_id bigint) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    org_name TEXT;
    view_name TEXT;
    view_sql TEXT;
    result_message TEXT;
    grant_sql TEXT;

BEGIN


    SELECT name INTO org_name
    FROM public.orgs
    WHERE id = p_org_id;

    IF org_name IS NULL THEN
        RAISE EXCEPTION 'No eligible organization found with org_id %', p_org_id;
    END IF;


    -- Sanitize name for use in view SQL identifier
    view_name := 'org_' || p_org_id || '_cameras';

    IF EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = 'overwatch' AND matviewname = view_name
    ) THEN
        -- Refresh if exists
        view_sql := format('REFRESH MATERIALIZED VIEW overwatch.%I;', view_name);
        EXECUTE view_sql;
        result_message := format('Refreshed materialized view: %s', view_name);

    ELSE
        -- Create if not exists
        view_sql := format(
                'CREATE MATERIALIZED VIEW overwatch.%I AS ' ||
                'SELECT oc.*,l.id as location_id, l.site_id ' ||
                'FROM overwatch.org_cameras_v2(%L) as oc ' ||
                'left join overwatch.cameras on cameras.id = oc.id ' ||
                'left join overwatch.locations l on cameras.location_id = l.id;',
                view_name,
                p_org_id
                    );

        EXECUTE view_sql;
        result_message := format('Created materialized view: %s', view_name);
        grant_sql := format(
                'alter materialized view overwatch.%I owner to overwatch',
                view_name
                     );
        EXECUTE grant_sql;

    END IF;
    RETURN result_message;

END;
$$;


--
-- Name: no_scans_in_illegal_states(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.no_scans_in_illegal_states() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	-- FOR REPO COMPANIES, scans not allowed in these listed states - mark as invisible
	IF NEW.is_visible AND EXISTS (select orgs.id FROM orgs JOIN kits ON (kits.org_id = orgs.id) WHERE kits.id=NEW.kit_id AND orgs.type=1) AND EXISTS (SELECT gid FROM tiger.state WHERE ST_Within(NEW.geo, simplified_geom) AND tiger.state.stusps IN ('AR', 'ME'))
	THEN
		NEW.is_visible = FALSE;
	END IF;

    RETURN NEW;
    END;

$$;


--
-- Name: p_aggregate_kit_user_scan_report(); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.p_aggregate_kit_user_scan_report()
    LANGUAGE sql
    AS $$

   WITH
    repos as materialized ( select * from platform.recoveries where
                                                         not exists( select recovery_id from aggregate_recoveries_kituser_scans_report where recovery_id = recoveries.id)
                                                         and repo_date >= now() - interval '1 month' and geo is not null ),
    scans_data as materialized (
        SELECT scans.kit_id,repos.id as recoveries_id, count(*) AS count
                                                            FROM scans
                                                            join repos on scans.ocr::text = repos.plate::text
                                                              AND scans.is_visible = true
                                                              AND st_dwithin(scans.geo::geometry,
                                                                             repos.geo::geometry,
                                                                             0.0014636::double precision)
                                                              AND scans.scanned_at >=
                                                                  ((((repos.repo_date - 90)::text) || ' 00:00:00'::text)::timestamp without time zone)
                                                              AND scans.scanned_at <=
                                                                  ((repos.repo_date::text || ' 23:59:59'::text)::timestamp without time zone)
                                                              AND (scans.kit_id IN (SELECT kits.id
                                                                                    FROM kits
                                                                                    WHERE kits.org_id = repos.org_id))
                                                            GROUP BY scans.kit_id, repos.id



    ),
    dataset AS (SELECT  repos.id,
                        repos.integration_id,
                        repos.remote_order_id,
                        repos.status,
                        repos.org_id,
                        repos.client_org_id,
                        repos.lienholder_org_id,
                        repos.order_type,
                        repos.is_staged,
                        repos.plate,
                        repos.us_state,
                        repos.vin,
                        repos.vehicle_year,
                        repos.vehicle_make,
                        repos.vehicle_model,
                        repos.lookback_days,
                        repos.created_at,
                        repos.updated_at,
                        repos.address_id,
                        repos.house_number,
                        repos.road,
                        repos.city,
                        repos.state,
                        repos.postcode,
                        repos.geo,
                        repos.repo_date,
                        hl_scans.kit_id,
                        hl_scans.count
                 FROM repos
                          LEFT JOIN LATERAL ( SELECT scans_data.kit_id,
                                                     sum(count) AS count
                                                            FROM scans_data
                                                            WHERE
                                                               scans_data.recoveries_id = repos.id
                                                            group by scans_data.kit_id) hl_scans ON true
                 -- where recoveries.id in (select id from repos)

                 ),
     hotlist_scan_count AS (SELECT dataset_1.id,
                                   sum(dataset_1.count) AS count
                            FROM dataset dataset_1
                            GROUP BY dataset_1.id)

insert into aggregate_recoveries_kituser_scans_report
   (recovery_id, integration_id, remote_order_id, status, org_id, client_org_id, lienholder_org_id, order_type, is_staged, plate, us_state, vin, vehicle_year, vehicle_make, vehicle_model, lookback_days, created_at, updated_at, address_id, house_number, road, city, state, postcode, geo, repo_date, kit_id, count, hotlist_scan_count, hotlist_scan_percentage)
SELECT dataset.id,
       dataset.integration_id,
       dataset.remote_order_id,
       dataset.status,
       dataset.org_id,
       dataset.client_org_id,
       dataset.lienholder_org_id,
       dataset.order_type,
       dataset.is_staged,
       dataset.plate,
       dataset.us_state,
       dataset.vin,
       dataset.vehicle_year,
       dataset.vehicle_make,
       dataset.vehicle_model,
       dataset.lookback_days,
       dataset.created_at,
       dataset.updated_at,
       dataset.address_id,
       dataset.house_number,
       dataset.road,
       dataset.city,
       dataset.state,
       dataset.postcode,
       dataset.geo,
       dataset.repo_date,
       dataset.kit_id,
       dataset.count,
       hotlist_scan_count.count                                                             AS hotlist_scan_count,
       dataset.count::numeric / NULLIF(hotlist_scan_count.count, 0::numeric) * 100::numeric AS hotlist_scan_percentage
FROM dataset
         JOIN hotlist_scan_count ON hotlist_scan_count.id = dataset.id

 on conflict (recovery_id, kit_id) do nothing


$$;


--
-- Name: p_geomfromfeaturecollection(json); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p_geomfromfeaturecollection(feature_collection json) RETURNS public.geometry
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

    declare
        new_geo geometry;
    begin
       WITH featureCollection AS (
        SELECT feature_collection AS fc
    ),
    geometries AS (
        SELECT (json_array_elements(fc->'features'))->'geometry' AS geo
        FROM featureCollection
    ),
    geojson AS (
        SELECT ST_Buffer(ST_MakeValid(ST_GeomFromGeoJSON(geo)), 0) AS geo
        FROM geometries
    )
    SELECT ST_SetSRID(ST_Union(geo), 4326) INTO new_geo
    FROM geojson;

    RETURN new_geo;

    end;


$$;


--
-- Name: procrastinate_defer_job(character varying, character varying, text, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_defer_job(queue_name character varying, task_name character varying, lock text, queueing_lock text, args jsonb, scheduled_at timestamp with time zone) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
	job_id bigint;
BEGIN
    INSERT INTO procrastinate_jobs (queue_name, task_name, lock, queueing_lock, args, scheduled_at)
    VALUES (queue_name, task_name, lock, queueing_lock, args, scheduled_at)
    RETURNING id INTO job_id;

    RETURN job_id;
END;
$$;


--
-- Name: procrastinate_defer_periodic_job(character varying, character varying, character varying, character varying, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_defer_periodic_job(_queue_name character varying, _lock character varying, _queueing_lock character varying, _task_name character varying, _defer_timestamp bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
	_job_id bigint;
	_defer_id bigint;
BEGIN

    INSERT
        INTO procrastinate_periodic_defers (task_name, queue_name, defer_timestamp)
        VALUES (_task_name, _queue_name, _defer_timestamp)
        ON CONFLICT DO NOTHING
        RETURNING id into _defer_id;

    IF _defer_id IS NULL THEN
        RETURN NULL;
    END IF;

    UPDATE procrastinate_periodic_defers
        SET job_id = procrastinate_defer_job(
                _queue_name,
                _task_name,
                _lock,
                _queueing_lock,
                ('{"timestamp": ' || _defer_timestamp || '}')::jsonb,
                NULL
            )
        WHERE id = _defer_id
        RETURNING job_id INTO _job_id;

    DELETE
        FROM procrastinate_periodic_defers
        USING (
            SELECT id
            FROM procrastinate_periodic_defers
            WHERE procrastinate_periodic_defers.task_name = _task_name
            AND procrastinate_periodic_defers.queue_name = _queue_name
            AND procrastinate_periodic_defers.defer_timestamp < _defer_timestamp
            ORDER BY id
            FOR UPDATE
        ) to_delete
        WHERE procrastinate_periodic_defers.id = to_delete.id;

    RETURN _job_id;
END;
$$;


--
-- Name: procrastinate_defer_periodic_job(character varying, character varying, character varying, character varying, character varying, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_defer_periodic_job(_queue_name character varying, _lock character varying, _queueing_lock character varying, _task_name character varying, _periodic_id character varying, _defer_timestamp bigint, _args jsonb) RETURNS bigint
    LANGUAGE plpgsql
    AS $$
DECLARE
	_job_id bigint;
	_defer_id bigint;
BEGIN

    INSERT
        INTO procrastinate_periodic_defers (task_name, periodic_id, defer_timestamp)
        VALUES (_task_name, _periodic_id, _defer_timestamp)
        ON CONFLICT DO NOTHING
        RETURNING id into _defer_id;

    IF _defer_id IS NULL THEN
        RETURN NULL;
    END IF;

    UPDATE procrastinate_periodic_defers
        SET job_id = procrastinate_defer_job(
                _queue_name,
                _task_name,
                _lock,
                _queueing_lock,
                _args,
                NULL
            )
        WHERE id = _defer_id
        RETURNING job_id INTO _job_id;

    DELETE
        FROM procrastinate_periodic_defers
        USING (
            SELECT id
            FROM procrastinate_periodic_defers
            WHERE procrastinate_periodic_defers.task_name = _task_name
            AND procrastinate_periodic_defers.periodic_id = _periodic_id
            AND procrastinate_periodic_defers.defer_timestamp < _defer_timestamp
            ORDER BY id
            FOR UPDATE
        ) to_delete
        WHERE procrastinate_periodic_defers.id = to_delete.id;

    RETURN _job_id;
END;
$$;


--
-- Name: procrastinate_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE UNLOGGED TABLE public.procrastinate_jobs (
    id bigint NOT NULL,
    queue_name character varying(128) NOT NULL,
    task_name character varying(128) NOT NULL,
    lock text,
    queueing_lock text,
    args jsonb DEFAULT '{}'::jsonb NOT NULL,
    status public.procrastinate_job_status DEFAULT 'todo'::public.procrastinate_job_status NOT NULL,
    scheduled_at timestamp with time zone,
    attempts integer DEFAULT 0 NOT NULL
)
WITH (fillfactor='80');


--
-- Name: procrastinate_fetch_job(character varying[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_fetch_job(target_queue_names character varying[]) RETURNS public.procrastinate_jobs
    LANGUAGE plpgsql
    AS $$
DECLARE
	found_jobs procrastinate_jobs;
BEGIN
    WITH candidate AS (
        SELECT jobs.*
            FROM procrastinate_jobs AS jobs
            WHERE
                -- reject the job if its lock has earlier jobs
                --NOT EXISTS (
                --    SELECT 1
                --        FROM procrastinate_jobs AS earlier_jobs
                --        WHERE
                --            jobs.lock IS NOT NULL
                --            AND earlier_jobs.lock = jobs.lock
                --            AND earlier_jobs.status IN ('todo', 'doing')
                --            AND earlier_jobs.id < jobs.id)
                -- AND jobs.status = 'todo'
				jobs.status = 'todo'
                AND (
						--target_queue_names IS NULL OR
						jobs.queue_name = ANY( target_queue_names )
					)
                -- AND (jobs.scheduled_at IS NULL
				      -- OR jobs.scheduled_at <= now()
				--	)
            -- ORDER BY jobs.id ASC
			LIMIT 1
            FOR UPDATE OF jobs SKIP LOCKED
    )
	-- SELECT candidate.* INTO found_jobs FROM candidate;
    UPDATE procrastinate_jobs
         SET status = 'doing'
         FROM candidate
         WHERE procrastinate_jobs.id = candidate.id
         RETURNING procrastinate_jobs.* INTO found_jobs;

	RETURN found_jobs;
END;
$$;


--
-- Name: procrastinate_finish_job(integer, public.procrastinate_job_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_finish_job(job_id integer, end_status public.procrastinate_job_status) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE procrastinate_jobs
    SET status = end_status,
        attempts = attempts + 1
    WHERE id = job_id;
END;
$$;


--
-- Name: procrastinate_finish_job(integer, public.procrastinate_job_status, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_finish_job(job_id integer, end_status public.procrastinate_job_status, next_scheduled_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE procrastinate_jobs
    SET status = end_status,
        attempts = attempts + 1,
        scheduled_at = COALESCE(next_scheduled_at, scheduled_at)
    WHERE id = job_id;
END;
$$;


--
-- Name: procrastinate_finish_job(integer, public.procrastinate_job_status, timestamp with time zone, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_finish_job(job_id integer, end_status public.procrastinate_job_status, next_scheduled_at timestamp with time zone, delete_job boolean) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    _job_id bigint;
BEGIN
    IF end_status NOT IN ('succeeded', 'failed') THEN
        RAISE 'End status should be either "succeeded" or "failed" (job id: %)', job_id;
    END IF;
    IF delete_job THEN
        DELETE FROM procrastinate_jobs
        WHERE id = job_id AND status IN ('todo', 'doing')
        RETURNING id INTO _job_id;
    ELSE
        UPDATE procrastinate_jobs
        SET status = end_status,
            attempts =
                CASE
                    WHEN status = 'doing' THEN attempts + 1
                    ELSE attempts
                END
        WHERE id = job_id AND status IN ('todo', 'doing')
        RETURNING id INTO _job_id;
    END IF;
    IF _job_id IS NULL THEN
        RAISE 'Job was not found or not in "doing" or "todo" status (job id: %)', job_id;
    END IF;
END;
$$;


