--
-- Name: procrastinate_trigger_status_events_procedure_update(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_trigger_status_events_procedure_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    WITH t AS (
        SELECT CASE
            WHEN OLD.status = 'todo'::procrastinate_job_status
                AND NEW.status = 'doing'::procrastinate_job_status
                THEN 'started'::procrastinate_job_event_type
            WHEN OLD.status = 'doing'::procrastinate_job_status
                AND NEW.status = 'todo'::procrastinate_job_status
                THEN 'deferred_for_retry'::procrastinate_job_event_type
            WHEN OLD.status = 'doing'::procrastinate_job_status
                AND NEW.status = 'failed'::procrastinate_job_status
                THEN 'failed'::procrastinate_job_event_type
            WHEN OLD.status = 'doing'::procrastinate_job_status
                AND NEW.status = 'succeeded'::procrastinate_job_status
                THEN 'succeeded'::procrastinate_job_event_type
            WHEN OLD.status = 'todo'::procrastinate_job_status
                AND (
                    NEW.status = 'failed'::procrastinate_job_status
                    OR NEW.status = 'succeeded'::procrastinate_job_status
                )
                THEN 'cancelled'::procrastinate_job_event_type
            ELSE NULL
        END as event_type
    )
    INSERT INTO procrastinate_events(job_id, type)
        SELECT NEW.id, t.event_type
        FROM t
        WHERE t.event_type IS NOT NULL;
	RETURN NEW;
END;
$$;


--
-- Name: procrastinate_unlink_periodic_defers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.procrastinate_unlink_periodic_defers() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE procrastinate_periodic_defers
    SET job_id = NULL
    WHERE job_id = OLD.id;
    RETURN OLD;
END;
$$;


--
-- Name: set_camera_last_scan(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_camera_last_scan() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.is_visible AND random() <= 0.05 THEN
		update overwatch.cameras set
	                             last_scan_date = new.scanned_at,
	                             properties['last_scan_guid'] = to_jsonb(new.guid),
								 properties['location'] = ('{"latitude":' || ST_Y(new.geo) || ', "longitude":' || ST_X(new.geo) || '}')::jsonb
	                         where id = NEW.kit_id;
	END IF;
   RETURN NEW;
END
$$;


--
-- Name: stop_scan_duplicates(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.stop_scan_duplicates() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	IF EXISTS (SELECT id FROM scans WHERE ocr=NEW.ocr AND kit_id=NEW.kit_id AND scanned_at=NEW.scanned_at AND is_visible AND NEW.is_visible)
	THEN
		NEW.is_visible = FALSE;
	END IF;

    RETURN NEW;
    END;

$$;


--
-- Name: sync_camera_geo_to_scans(integer, date, date); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.sync_camera_geo_to_scans(IN p_kit_id integer, IN date_from date, IN date_to date)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_geo GEOMETRY;
BEGIN
    -- Select the geo value from the cameras table
    SELECT ST_SETSRID(cameras.geo, 4326) INTO v_geo
    FROM public.kits
    JOIN overwatch.cameras ON cameras.id = kits.id
    WHERE kits.id = p_kit_id;

    -- Update the scans table with the selected geo value
    UPDATE public.scans
    SET geo = v_geo,
        is_visible = true
    WHERE is_visible = false and kit_id = p_kit_id and scans.scanned_at BETWEEN date_from and date_to;
END $$;


--
-- Name: update_or_insert_camera(integer); Type: PROCEDURE; Schema: public; Owner: -
--

CREATE PROCEDURE public.update_or_insert_camera(IN p_kit_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    p_location_id INT;
    p_territory_id INT;
    p_site_id INT;
    p_org_id INT;
    p_old_location_id INT;
BEGIN
    select kits.org_id, coalesce(ot.id,0), coalesce(os.id,0), coalesce(ol.id,0) from public.kits
           left join lateral (select id from overwatch.territories where kits.org_id = territories.org_id order by created_at desc limit 1) ot on true
           left join lateral (select id from overwatch.sites where ot.id = sites.territory_id order by created_at desc limit 1) os on true
           left join lateral (select id from overwatch.locations where os.id = locations.site_id order by created_at desc limit 1) ol on true
    where public.kits.id = p_kit_id into p_org_id, p_territory_id, p_site_id, p_location_id;

    -- RAISE EXCEPTION 'org_id: %, territory_id: %, site_id: %, location_id: %', p_org_id, p_territory_id, p_site_id, p_location_id;

        if p_territory_id = 0 then
            insert into overwatch.territories (org_id, name, created_at) values (p_org_id, 'Default', now()) returning id into p_territory_id;
        end if;

        if p_site_id = 0 then
            insert into overwatch.sites (territory_id, name, address_id, created_at) values (p_territory_id, 'Default', 1, now()) returning id into p_site_id;
        end if;

        if p_location_id = 0 then
            insert into overwatch.locations (site_id, name, created_at) values (p_site_id, 'Default', now()) returning id into p_location_id;
        end if;

    select coalesce(location_id, 0) from overwatch.cameras where id = p_kit_id into p_old_location_id;

    if p_old_location_id = p_location_id or exists(select territories.org_id from overwatch.locations
             join overwatch.sites on sites.id = locations.site_id
             join overwatch.territories on territories.id = sites.territory_id
             where locations.id = p_old_location_id and territories.org_id = p_org_id)
        then
        return;
    end if;

    IF p_old_location_id > 0  THEN
        UPDATE overwatch.cameras SET location_id = p_location_id, updated_at=now() WHERE id = p_kit_id;

        INSERT INTO overwatch.activity_log (subject_type, subject_id, log_name, description, properties, created_at,updated_at)
        VALUES ('camera', p_kit_id, 'updated','location changed by proc', json_build_object('old',p_old_location_id, 'new',p_location_id), now(), now());
    ELSE
        INSERT INTO overwatch.cameras (id, location_id, created_at, updated_at) VALUES (p_kit_id, p_location_id, now(), now());
    END IF;

END;
$$;


--
-- Name: update_overwatch_camera_func(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_overwatch_camera_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

   UPDATE public.kits SET name = NEW.name,
                          kit_mapping = NEW.kit_mapping,
                          kit_type = NEW.kit_type,
                          org_id = NEW.org_id
                      WHERE id = NEW.id;
   UPDATE overwatch.cameras SET location_id = NEW.location_id, updated_at = now(),properties=NEW.properties, deleted_at=NEW.deleted_at WHERE id = NEW.id;
   RETURN NEW;
END
$$;


--
-- Name: update_scans_metadata(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_scans_metadata() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO scans_metadata (scan_id, meta)
    VALUES (
               NEW.scan_id,
               (SELECT jsonb_object_agg(meta_type, meta_value)
                FROM scans_meta
                WHERE scan_id = NEW.scan_id)
           )
    ON CONFLICT (scan_id)
        DO UPDATE SET
        meta = scans_metadata.meta || EXCLUDED.meta;

    RETURN NEW;
END;
$$;


--
-- Name: user_cameras_w(bigint, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_cameras_w(user_id_param bigint, commercial boolean DEFAULT true, owned boolean DEFAULT true) RETURNS SETOF overwatch.user_camera
    LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
    AS $$

    DECLARE
        org_id_variable BIGINT;
        org_type_variable INT;
        org_commercial_data_feed_variable BOOLEAN;

BEGIN
       PERFORM set_config('max_worker_processes', '8', false);

        select orgs.type,
               orgs.id as id,
                 CASE WHEN org_meta.properties->>'commercial_data_feed' = 'true' THEN true ELSE false END
        from public.orgs
         left join public.org_meta on orgs.id = org_meta.id
         join overwatch.users on users.org_id = orgs.id
         where users.id = user_id_param into org_type_variable, org_id_variable, org_commercial_data_feed_variable;


        IF commercial = TRUE and owned = TRUE THEN

    RETURN QUERY
        with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_variable))

        select kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               false as is_shared
        from public.kits
            join overwatch.cameras on cameras.id = kits.id
            join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_variable and locations.site_id in (select id from overwatch.user_sites(user_id_param))

            UNION ALL
                select * from org_shared_cameras
            UNION ALL

            select kits.id,
               'Commercial'::varchar as name,
               kits.kit_type,
               kits.org_id,
               true as is_commercial,
               false as is_shared
            from public.kits
            join public.orgs on orgs.id = kits.org_id
            where org_id != org_id_variable
              and orgs.type != 4
              and org_commercial_data_feed_variable = true
              and kits.id not in (select id from org_shared_cameras)
    ;

    ELSEIF commercial = TRUE AND owned = FALSE THEN
        RETURN QUERY
            with org_shared_cameras as ( select * from overwatch.org_shared_cameras(org_id_variable))
            select kits.id,
               'Commercial'::varchar as name,
               kits.kit_type,
               kits.org_id,
               true as is_commercial,
               false as is_shared
            from public.kits
            join orgs as po on po.id = kits.org_id
            where org_id != org_id_variable and po.type != 4 and org_commercial_data_feed_variable = true
           and kits.id not in (select id from org_shared_cameras)
        ;


    ELSEIF commercial = FALSE AND owned = TRUE THEN
        RETURN QUERY
            select kits.id,
               kits.name,
               kits.kit_type,
               kits.org_id,
               false as is_commercial,
               false as is_shared
        from public.kits
            join overwatch.cameras on cameras.id = kits.id
            join overwatch.locations on locations.id = cameras.location_id
            where kits.org_id = org_id_variable and locations.site_id in (select id from overwatch.user_sites(user_id_param))
        UNION ALL
            select * from overwatch.org_shared_cameras(org_id_variable);
        END IF;


END; $$;


--
-- Name: weird_scan_patterns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.weird_scan_patterns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
	IF NEW.ocr LIKE '%III%' OR LENGTH(NEW.ocr) <=3
	THEN
		NEW.is_visible = FALSE;
	END IF;

    RETURN NEW;
    END;

$$;


--
-- Name: cameras; Type: TABLE; Schema: overwatch; Owner: -
