CREATE TABLE overwatch.cameras (
    id bigint NOT NULL,
    location_id bigint NOT NULL,
    created_at timestamp(0) without time zone,
    updated_at timestamp(0) without time zone,
    deleted_at timestamp(0) without time zone,
    properties jsonb DEFAULT '{}'::jsonb,
    geo public.geometry GENERATED ALWAYS AS (public.st_point((((properties -> 'location'::text) ->> 'longitude'::text))::double precision, (((properties -> 'location'::text) ->> 'latitude'::text))::double precision)) STORED,
    status integer DEFAULT 1,
    deployment_type integer DEFAULT 2,
    disposition integer DEFAULT 1 NOT NULL,
    status_notification timestamp without time zone,
    last_scan_date timestamp without time zone,
    flakey boolean DEFAULT false,
    CONSTRAINT check_warranty_date_format CHECK (overwatch.validate_warranty_date(properties))
)
WITH (autovacuum_analyze_scale_factor='0.25', autovacuum_vacuum_scale_factor='0.25', autovacuum_analyze_threshold='1200', autovacuum_vacuum_threshold='1200', autovacuum_enabled='false');


