--
-- Name: cameras_view; Type: VIEW; Schema: bizintel; Owner: -
--

CREATE VIEW bizintel.cameras_view AS
 SELECT kits.id,
    kits.kit_mapping,
    kits.name,
    kits.org_id,
    cameras.disposition,
    cameras.status,
    cameras.last_scan_date,
    orgs.name AS org_name,
    (cameras.properties ->> 'port'::text) AS port,
    (cameras.properties ->> 'ip_address'::text) AS ip,
    (cameras.properties ->> 'installation_date'::text) AS installation_date,
    (cameras.properties ->> 'warranty_expiration_date'::text) AS warranty_expiration_date,
    (cameras.properties ->> 'deployment_type'::text) AS deployment_type,
    cameras.properties
   FROM ((overwatch.cameras
     JOIN public.kits ON ((kits.id = cameras.id)))
     JOIN public.orgs ON ((orgs.id = kits.org_id)))
  WHERE ((kits.id <> '-1'::integer) AND (orgs.type <> ALL (ARRAY[1, 2, 3])) AND (cameras.deleted_at IS NULL));


