-- Name: aggregate_scan_count_h; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.aggregate_scan_count_h (
    timeblock integer NOT NULL,
    kit_id integer NOT NULL,
    scan_count integer DEFAULT 0 NOT NULL,
    id bigint DEFAULT nextval('public.aggregate_scan_count_h_seq'::regclass) NOT NULL,
    scanned_at timestamp without time zone GENERATED ALWAYS AS (to_timestamp((((timeblock)::bigint * 3600))::double precision)) STORED
);


--
-- Name: aggregated_scans_by_month; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.aggregated_scans_by_month AS
 SELECT date_trunc('month'::text, aggregate_scan_count_h.scanned_at) AS period,
    sum(aggregate_scan_count_h.scan_count) AS scan_count,
    orgs.type
   FROM ((public.aggregate_scan_count_h
     JOIN public.kits ON ((kits.id = aggregate_scan_count_h.kit_id)))
     JOIN public.orgs ON ((orgs.id = kits.org_id)))
  WHERE (aggregate_scan_count_h.scanned_at >= (now() - '1 year'::interval))
  GROUP BY (date_trunc('month'::text, aggregate_scan_count_h.scanned_at)), orgs.type
  WITH NO DATA;


