--
-- Name: alerts_view; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.alerts_view AS
 SELECT hits.id,
    hits.created_at,
    hits.hotlist_id,
    hits.scan_id,
    scans.kit_id,
    scans.geo AS scan_geo,
    integrations_view.org_id,
    integrations_view.name AS hotlist_name,
    integrations_view.shared AS hotlist_is_shared,
    integrations_view.mapping_type,
    integrations_view.mapping_id,
    (sm.metadata ->> '1'::text) AS vehicle_type,
    (sm.metadata ->> '2'::text) AS vehicle_color,
    (sm.metadata ->> '3'::text) AS vehicle_make,
    (sm.metadata ->> '4'::text) AS is_not_plate,
    (sm.metadata ->> '5'::text) AS ml_plate_state,
    (sm.metadata ->> '6'::text) AS scan_address,
    sm.metadata,
    hotlist.plate AS hotlist_plate,
    hotlist.us_state AS hotlist_us_state,
    hotlist.integration_id,
    scanner_org.id AS scanner_org_id,
    scanner_org.name AS scanner_org_name,
    scanner_org.type AS scanner_org_type,
    hotlist.vin AS hotlist_vin,
    hotlist.vehicle_make AS hotlist_vehicle_make,
    hotlist.vehicle_model AS hotlist_vehicle_model,
    hotlist.vehicle_year AS hotlist_vehicle_year,
    hotlist.remote_order_id AS hotlist_case,
    public.st_x(scans.geo) AS scan_longitude,
    public.st_y(scans.geo) AS scan_latitude
   FROM (((((((public.hits
     JOIN public.scans ON ((scans.id = hits.scan_id)))
     JOIN public.kits ON ((kits.id = hits.kit_id)))
     JOIN public.orgs scanner_org ON ((scanner_org.id = kits.org_id)))
     JOIN public.hotlist ON ((hotlist.id = hits.hotlist_id)))
     JOIN public.integrations_view ON ((integrations_view.id = hotlist.integration_id)))
     JOIN public.orgs ON ((orgs.id = integrations_view.org_id)))
     LEFT JOIN LATERAL ( SELECT json_object_agg(scans_meta.meta_type, scans_meta.meta_value) AS metadata
           FROM public.scans_meta
          WHERE (hits.scan_id = scans_meta.scan_id)
          GROUP BY scans_meta.scan_id) sm ON (true))
  WHERE ((hits.hit_type = 'O'::bpchar) AND (hotlist.status = 1));


