--
-- Name: camera_status; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.camera_status AS
 WITH dataset AS (
         SELECT cameras.id,
            cameras.deployment_type,
            (cameras.properties ->> 'last_scan_date'::text) AS last_scan_date,
                CASE
                    WHEN ((cameras.properties ->> 'last_scan_date'::text) IS NULL) THEN 2
                    ELSE
                    CASE
                        WHEN ((cameras.deployment_type = 0) AND ((cameras.properties ->> 'last_scan_date'::text) < ((now() - '7 days'::interval))::text)) THEN 2
                        WHEN ((cameras.deployment_type = 1) AND ((cameras.properties ->> 'last_scan_date'::text) < ((now() - '45 days'::interval))::text)) THEN 2
                        WHEN ((cameras.properties ->> 'last_scan_date'::text) < ((now() - '06:00:00'::interval))::text) THEN 2
                        ELSE 1
                    END
                END AS camera_status,
            cameras.status_notification
           FROM ((overwatch.cameras
             JOIN public.kits ON ((cameras.id = kits.id)))
             JOIN public.orgs ON ((orgs.id = kits.org_id)))
          WHERE ((cameras.deleted_at IS NULL) AND (cameras.disposition = 1) AND ((cameras.properties ->> 'last_scan_date'::text) IS NOT NULL) AND ((kits.kit_mapping)::text !~~* '%TERM%'::text) AND (kits.kit_type <> 1) AND (orgs.type <> ALL (ARRAY[1, 2, 3])) AND (kits.org_id <> ALL (ARRAY[1, 3, 281531])))
        )
 SELECT id,
    deployment_type,
    last_scan_date,
    camera_status,
        CASE
            WHEN (camera_status = 2) THEN (status_notification)::character varying
            ELSE ''::character varying
        END AS status_notification
   FROM dataset
  WITH NO DATA;


