--
-- Name: integration_connection_overview; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.integration_connection_overview AS
 SELECT DISTINCT ON (eic.id) eic.id AS connection_id,
    eic.integration_id,
    integrations.name,
    eic.run_interval,
        CASE
            WHEN (eic.file_type = 1) THEN 'CSV'::character varying
            WHEN (eic.file_type = 2) THEN 'NCIC'::character varying
            WHEN (eic.file_type = 3) THEN 'SVS'::character varying
            WHEN (eic.file_type = 4) THEN 'CSV LATHROP'::character varying
            ELSE (eic.file_type)::character varying
        END AS file_type,
    activity_log.log_name,
    activity_log.description,
    activity_log.properties,
    activity_log.id AS activity_log_id,
    ((activity_log.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'America/New_York'::text) AS last_run_at_eastern_time,
    ((eic.created_at AT TIME ZONE 'UTC'::text) AT TIME ZONE 'America/New_York'::text) AS connection_created_at_eastern_time
   FROM (((overwatch.external_integration_connections eic
     JOIN public.integrations ON ((eic.integration_id = integrations.id)))
     LEFT JOIN overwatch.activity_log ON (((activity_log.causer_id = eic.integration_id) AND ((activity_log.causer_type)::text = 'integrations'::text))))
     LEFT JOIN ( SELECT activity_log_1.causer_id,
            max(activity_log_1.created_at) AS max_created_at
           FROM overwatch.activity_log activity_log_1
          WHERE ((activity_log_1.causer_type)::text = 'integrations'::text)
          GROUP BY activity_log_1.causer_id) subq ON (((activity_log.causer_id = subq.causer_id) AND (activity_log.created_at = subq.max_created_at) AND (subq.causer_id = eic.integration_id))));


