--
-- Name: kit_integrations; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.kit_integrations AS
 WITH foo AS (
         SELECT DISTINCT users.id AS user_id,
            kits.id AS kit_id,
            (jsonb_array_elements((users.settings -> 'integration_ids'::text)))::bigint AS integration_id
           FROM ((public.kits
             JOIN public.orgs ON ((kits.org_id = orgs.id)))
             JOIN overwatch.users ON ((((users.settings ->> 'assigned_camera'::text))::bigint = kits.id)))
          WHERE ((kits.kit_type = 1) AND (orgs.type = 4))
        )
 SELECT user_id,
    kit_id,
    integration_id
   FROM foo
  WHERE (EXISTS ( SELECT 1
           FROM overwatch.user_hotlists(foo.user_id) uh(id, name, status, batch_id, mapping_id, mapping_type, org_id, shared)
          WHERE (uh.id = foo.integration_id)))
  WITH NO DATA;


--
-- Name: kit_hotlists; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.kit_hotlists AS
 SELECT kit_integrations.user_id,
    kit_integrations.kit_id,
    hotlist.id,
    hotlist.integration_id,
    hotlist.remote_order_id,
    hotlist.status,
    hotlist.org_id,
    hotlist.plate,
    hotlist.us_state,
    hotlist.vin,
    hotlist.vehicle_year,
    hotlist.vehicle_make,
    hotlist.vehicle_model,
    hotlist.created_at,
    hotlist.updated_at
   FROM (overwatch.kit_integrations
     JOIN public.hotlist ON ((kit_integrations.integration_id = hotlist.integration_id)))
  WHERE (hotlist.status = 1);


