    kits.name,
    kits.text_phone,
    cameras.created_at,
    cameras.updated_at,
    cameras.deleted_at,
    cameras.properties,
    cameras.geo,
    cameras.last_scan_date,
    cameras.status,
    cameras.deployment_type,
    cameras.status_notification,
    cameras.disposition,
    cameras.flakey
   FROM (overwatch.cameras
     JOIN public.kits ON ((cameras.id = kits.id)));


--
-- Name: org_cameras; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.org_cameras AS
 SELECT overwatch_cameras.id AS camera_id,
    overwatch_cameras.org_id,
    false AS shared,
    overwatch_cameras.org_id AS owner_org_id,
    overwatch_cameras.location_id
   FROM overwatch.overwatch_cameras
UNION
 SELECT shared.shared_id AS camera_id,
    shared.shared_with_id AS org_id,
    true AS shared,
    overwatch_cameras.org_id AS owner_org_id,
    overwatch_cameras.location_id
   FROM (overwatch.shared
     JOIN overwatch.overwatch_cameras ON ((overwatch_cameras.id = shared.shared_id)))
  WHERE (((shared.shared_type)::text = 'cameras'::text) AND ((shared.shared_with_type)::text = 'org'::text));


