    orgs.irepo_id,
    orgs.enable_genetech_hotlist,
    orgs.enable_matrix_hotlist,
    orgs.silent_hit_generation,
    orgs.ls_id,
    territories.id AS territory_id,
    territories.name AS territory_name,
    sites.id AS site_id,
    sites.name AS site_name,
    sites.address_id AS site_address_id
   FROM ((public.orgs
