     JOIN overwatch.sites ON ((territories.id = sites.territory_id)));


--
-- Name: org_states; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.org_states AS
 SELECT orgs.id AS org_id,
    state.name AS state_name
   FROM (((public.orgs
     JOIN public.kits ON ((kits.org_id = orgs.id)))
     JOIN overwatch.cameras ON ((cameras.id = kits.id)))
     JOIN tiger.state ON (public.st_within(public.st_setsrid(cameras.geo, 4269), state.the_geom)))
  WHERE ((cameras.deleted_at IS NULL) AND (cameras.disposition = 1) AND (orgs.id <> '-1'::integer))
  GROUP BY orgs.id, orgs.name, state.name;


