--
-- Name: user_alert_settings; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.user_alert_settings AS
 WITH user_info AS MATERIALIZED (
         SELECT users.id AS userid,
            lower((users.email)::text) AS useremail,
            regexp_replace((users.mobile_phone)::text, '[^0-9]'::text, ''::text, 'g'::text) AS userphone
           FROM overwatch.users
        )
 SELECT alert_settings.id,
    alert_settings.name,
    alert_settings.alertable_type,
    alert_settings.alertable_id,
    alert_settings.commercial_area_geo,
    alert_settings.settings,
    alert_settings.created_at,
    alert_settings.updated_at,
    alert_settings.deleted_at,
    alert_settings.type,
    alert_settings.org_id,
    unnamed_subquery.userid,
    unnamed_subquery.userphone,
    unnamed_subquery.useremail
   FROM (overwatch.alert_settings
     JOIN LATERAL ( SELECT user_info.userid,
            user_info.userphone,
            user_info.useremail
           FROM user_info) unnamed_subquery ON (true))
  WHERE (((((alert_settings.settings -> 'notifications'::text) -> 'sms'::text) <> '[]'::jsonb) OR (((alert_settings.settings -> 'notifications'::text) -> 'emails'::text) <> '[]'::jsonb) OR (((alert_settings.settings -> 'notifications'::text) -> 'alerter'::text) <> '[]'::jsonb)) AND ((EXISTS ( SELECT 1
           FROM jsonb_array_elements(((alert_settings.settings -> 'notifications'::text) -> 'emails'::text)) email(value)
          WHERE ((((alert_settings.settings -> 'notifications'::text) -> 'emails'::text) <> '[]'::jsonb) AND (lower((email.value ->> 'email'::text)) = lower(unnamed_subquery.useremail))))) OR (EXISTS ( SELECT 1
           FROM jsonb_array_elements(((alert_settings.settings -> 'notifications'::text) -> 'alerter'::text)) alerter(value)
          WHERE ((((alert_settings.settings -> 'notifications'::text) -> 'alerter'::text) <> '[]'::jsonb) AND ((alerter.value)::text = (unnamed_subquery.userid)::text)))) OR (EXISTS ( SELECT 1
           FROM jsonb_array_elements(((alert_settings.settings -> 'notifications'::text) -> 'sms'::text)) phone(value)
          WHERE ((((alert_settings.settings -> 'notifications'::text) -> 'sms'::text) <> '[]'::jsonb) AND ((phone.value ->> 'phone'::text) IS NOT NULL) AND ((phone.value ->> 'phone'::text) <> ''::text) AND ((phone.value ->> 'phone'::text) = unnamed_subquery.userphone))))) AND (alert_settings.deleted_at IS NULL));


--
-- Name: orgs_dps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.orgs_dps (
    org_id bigint NOT NULL
);


--
-- Name: user_assigned_camera_integrations; Type: VIEW; Schema: overwatch; Owner: -
--

CREATE VIEW overwatch.user_assigned_camera_integrations AS
 SELECT (users.settings ->> 'assigned_camera'::text) AS kit_id,
    jsonb_agg(DISTINCT integrations_view.id) AS integration_ids
   FROM (overwatch.users
     JOIN public.integrations_view ON ((integrations_view.org_id = users.org_id)))
  WHERE ((users.settings IS NOT NULL) AND (users.deleted_at IS NULL) AND ((integrations_view.status)::text = 'active'::text) AND (EXISTS ( SELECT 1
           FROM overwatch.cameras
          WHERE (((users.settings ->> 'assigned_camera'::text) ~ '^\d+$'::text) AND (cameras.id = ((users.settings ->> 'assigned_camera'::text))::bigint) AND ((users.settings ->> 'assigned_camera'::text) IS NOT NULL) AND ((users.settings ->> 'assigned_camera'::text) <> '[]'::text) AND (cameras.deleted_at IS NULL)))) AND (users.settings <> '{}'::jsonb) AND (((((users.settings -> 'integration_ids'::text) IS NOT NULL) OR ((users.settings -> 'integration_ids'::text) <> '[]'::jsonb)) AND ((integrations_view.mapping_type)::text = 'org'::text) AND (integrations_view.shared = false)) OR ((((users.settings -> 'integration_ids'::text) IS NULL) OR ((users.settings -> 'integration_ids'::text) = '[]'::jsonb)) AND ((integrations_view.mapping_type)::text = 'org'::text) AND (integrations_view.shared = false)) OR (((users.settings ->> 'send_personal_hotlists'::text) = 'true'::text) AND ((integrations_view.mapping_type)::text = 'user'::text) AND (integrations_view.mapping_id = users.id) AND (integrations_view.shared = false)) OR (((users.settings ->> 'send_shared_hotlists'::text) = 'true'::text) AND (integrations_view.shared = true))) AND (NOT (integrations_view.id IN ( SELECT integrations.id
           FROM public.integrations
          WHERE (((integrations.mapping_type)::text = 'org'::text) AND (integrations.mapping_id IN ( SELECT orgs_dps.org_id
                   FROM public.orgs_dps)))))))
  GROUP BY (users.settings ->> 'assigned_camera'::text);


--
-- Name: user_sites_view; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.user_sites_view AS
 SELECT sites.id AS site_id,
    users.id AS user_id
   FROM (((overwatch.users
     JOIN public.orgs ON ((orgs.id = users.org_id)))
     JOIN overwatch.territories ON ((territories.org_id = users.org_id)))
     JOIN overwatch.sites ON ((sites.territory_id = territories.id)))
  WHERE ((orgs.type <> ALL (ARRAY[1, 2, 3])) AND (sites.deleted_at IS NULL) AND (territories.deleted_at IS NULL) AND (users.deleted_at IS NULL) AND
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM overwatch.shared
              WHERE (((shared.shared_type)::text = 'sites'::text) AND (shared.shared_with_id = users.id) AND (shared.deleted_at IS NULL) AND ((shared.shared_with_type)::text = 'user'::text)))) THEN (sites.id IN ( SELECT shared.shared_id
               FROM overwatch.shared
              WHERE ((shared.shared_id = sites.id) AND ((shared.shared_type)::text = 'sites'::text) AND (shared.shared_with_id = users.id) AND (shared.deleted_at IS NULL) AND ((shared.shared_with_type)::text = 'user'::text))))
            ELSE true
        END)
  WITH NO DATA;


--
-- Name: user_cameras; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.user_cameras AS
 WITH dc AS (
         SELECT oc.id,
            oc.name,
            oc.kit_type,
            oc.org_id,
            oc.is_commercial,
            oc.is_shared,
            user_sites_view.site_id,
            user_sites_view.user_id,
            locations.id AS location_id
           FROM ((((overwatch.user_sites_view
             JOIN overwatch.users ON ((users.id = user_sites_view.user_id)))
             CROSS JOIN LATERAL overwatch.org_cameras(users.org_id) oc(id, name, kit_type, org_id, is_commercial, is_shared))
             LEFT JOIN overwatch.cameras ON ((cameras.id = oc.id)))
             LEFT JOIN overwatch.locations ON ((locations.id = cameras.location_id)))
          WHERE ((cameras.deleted_at IS NULL) AND (locations.deleted_at IS NULL) AND
                CASE
                    WHEN (oc.is_commercial OR oc.is_shared) THEN true
                    ELSE (locations.site_id = user_sites_view.site_id)
                END)
        )
 SELECT id,
    name,
    kit_type,
    org_id,
    is_commercial,
    is_shared,
    site_id,
    user_id,
    location_id
   FROM dc
  WITH NO DATA;


