--
-- Name: user_activity_log; Type: VIEW; Schema: platform; Owner: -
--

CREATE VIEW platform.user_activity_log AS
 SELECT users.name AS user_name,
    users.id AS user_id,
    ((activity_log.properties -> 'session'::text) ->> 'ip'::text) AS ip_address,
    activity_log.id,
    activity_log.log_name,
    activity_log.causer_type,
    activity_log.causer_id,
    activity_log.subject_id,
    activity_log.subject_type,
    activity_log.description,
    activity_log.properties,
    activity_log.batch_uuid,
    activity_log.event,
    activity_log.created_at,
    orgs.name,
    orgs.id AS org_id,
    ((activity_log.properties -> 'impersonator'::text) ->> 'name'::text) AS impersonator_name,
    ((activity_log.properties -> 'impersonator'::text) ->> 'id'::text) AS impersonator_id
   FROM ((platform.activity_log
     JOIN platform.users ON (((users.id = activity_log.causer_id) AND ((activity_log.causer_type)::text = 'user'::text))))
     JOIN public.orgs ON ((orgs.id = users.org_id)));


