    id integer NOT NULL,
    hotlist_id bigint NOT NULL,
    address_id bigint NOT NULL
);


--
-- Name: aggregate_address_geohash; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.aggregate_address_geohash AS
 SELECT public.st_geohash(geo, 5) AS geohash,
    count(public.st_geohash(geo, 5)) AS count,
    public.st_geomfromgeohash(public.st_geohash(geo, 5)) AS geom
   FROM ( SELECT DISTINCT address.geo
           FROM ((public.address
             JOIN public.hotlist_address ON ((hotlist_address.address_id = address.id)))
             JOIN public.hotlist ON (((hotlist.id = hotlist_address.hotlist_id) AND (hotlist.status = 1))))) t
  GROUP BY (public.st_geohash(geo, 5))
  WITH NO DATA;


--
-- Name: aggregate_address_geohash6; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.aggregate_address_geohash6 AS
 SELECT public.st_geohash(geo, 6) AS geohash,
    count(public.st_geohash(geo, 6)) AS count,
    public.st_geomfromgeohash(public.st_geohash(geo, 6)) AS geom
   FROM ( SELECT DISTINCT address.geo
           FROM ((public.address
             JOIN public.hotlist_address ON ((hotlist_address.address_id = address.id)))
             JOIN public.hotlist ON (((hotlist.id = hotlist_address.hotlist_id) AND (hotlist.status = 1))))
          WHERE (address.geo IS NOT NULL)) t
  GROUP BY (public.st_geohash(geo, 6))
  WITH NO DATA;


