-- Name: us_zipcodes; Type: TABLE; Schema: tiger; Owner: -
--

CREATE TABLE tiger.us_zipcodes (
    zip_code character varying NOT NULL,
    area double precision,
    the_geom public.geometry NOT NULL,
    population integer DEFAULT 0,
    state character varying,
    geom_4326 public.geometry GENERATED ALWAYS AS (public.st_transform(the_geom, 4326)) STORED,
    geom_4326_simple public.geometry GENERATED ALWAYS AS (public.st_simplify(public.st_transform(the_geom, 4326), (0.001)::double precision)) STORED
);


--
-- Name: aggregate_address_heatmap; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.aggregate_address_heatmap AS
 SELECT zip_code,
    state,
    population,
    area,
    ( SELECT count(DISTINCT address.geo) AS count
           FROM (public.address
             JOIN public.hotlist_address ON ((address.id = hotlist_address.address_id)))
          WHERE public.st_within(address.geo, us_zipcodes.geom_4326_simple)) AS addresses,
    geom_4326 AS geom
   FROM tiger.us_zipcodes
  WITH NO DATA;


