-- Name: timezones; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.timezones (
    gid integer NOT NULL,
    tzid character varying(80),
    geom public.geometry(MultiPolygon,4326),
    original_geom public.geometry
);


--
-- Name: aggregate_kit_scan_path_h; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.aggregate_kit_scan_path_h AS
 SELECT kit_id,
    geo,
    "timestamp"
   FROM ( SELECT scans.kit_id,
            public.st_removerepeatedpoints(public.st_makevalid(public.st_makeline(scans.geo ORDER BY scans.scanned_at))) AS geo,
            date_bin('01:00:00'::interval,
                CASE
                    WHEN (timezones.tzid IS NOT NULL) THEN (((scans.scanned_at AT TIME ZONE timezones.tzid) AT TIME ZONE 'utc'::text))::timestamp with time zone
                    ELSE (scans.scanned_at AT TIME ZONE 'utc'::text)
                END, '2023-03-01 00:00:00+00'::timestamp with time zone) AS "timestamp"
           FROM ((public.scans
             LEFT JOIN public.timezones ON (public.st_within(scans.geo, timezones.geom)))
             JOIN public.kits k ON (((scans.kit_id = k.id) AND (k.kit_type = ANY (ARRAY[1, 5])))))
          WHERE ((public.st_x(scans.geo) <> (0)::double precision) AND (scans.scanned_at > (now() - '2 mons'::interval)) AND (k.org_id <> ALL (ARRAY[1, 3, 5])) AND scans.is_visible)
          GROUP BY scans.kit_id, (date_bin('01:00:00'::interval,
                CASE
                    WHEN (timezones.tzid IS NOT NULL) THEN (((scans.scanned_at AT TIME ZONE timezones.tzid) AT TIME ZONE 'utc'::text))::timestamp with time zone
                    ELSE (scans.scanned_at AT TIME ZONE 'utc'::text)
                END, '2023-03-01 00:00:00+00'::timestamp with time zone))) trips
  WHERE (public.st_length(geo) > (0)::double precision)
  WITH NO DATA;


--
-- Name: aggregate_org_type_scan_count_m; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.aggregate_org_type_scan_count_m AS
 SELECT date_trunc('month'::text, aggregate_scan_count_h.scanned_at) AS scanned_at,
    sum(aggregate_scan_count_h.scan_count) AS scan_count,
    orgs.type AS org_type
   FROM ((public.aggregate_scan_count_h
     JOIN public.kits ON ((kits.id = aggregate_scan_count_h.kit_id)))
     JOIN public.orgs ON ((orgs.id = kits.org_id)))
  GROUP BY (date_trunc('month'::text, aggregate_scan_count_h.scanned_at)), orgs.type
  WITH NO DATA;


