);


--
-- Name: lexisnexis_companies; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.lexisnexis_companies AS
 SELECT orgs.id,
    orgs.name,
    orgs.address_id,
    orgs.type,
    orgs.rdn_id,
    orgs.rdn_api_key,
    orgs.irepo_id,
    orgs.enable_genetech_hotlist,
    orgs.enable_matrix_hotlist,
    orgs.silent_hit_generation,
    orgs.ls_id,
    (org_meta.properties ->> 'agency_ori'::text) AS agency_ori,
    (org_meta.properties ->> 'lexisnexis_company_id'::text) AS lexisnexis_company_id,
    org_meta.properties
   FROM (public.orgs
     JOIN public.org_meta ON ((orgs.id = org_meta.id)))
  WHERE (((org_meta.properties ->> 'lexisnexis_company_id'::text) IS NOT NULL) AND ((org_meta.properties ->> 'lexisnexis_company_id'::text) <> ''::text));


