--
-- Name: org_data_export_hits; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_data_export_hits AS
 SELECT hits.id AS hit_id,
    scans.guid AS scan_guid,
    scans.id AS scan_id,
    scans.geo AS scan_geo,
    scans.scanned_at AS scan_scanned_at,
    sm.metadata,
    (sm.metadata ->> '1'::text) AS vehicle_type,
    (sm.metadata ->> '2'::text) AS vehicle_color,
    (sm.metadata ->> '3'::text) AS vehicle_make,
    (sm.metadata ->> '4'::text) AS scan_address,
    public.st_x((scans.geo)::public.geometry) AS scan_longitude,
    public.st_y((scans.geo)::public.geometry) AS scan_latitude,
    oc.is_commercial AS scan_is_commercial,
    oc.is_shared AS scan_is_shared,
    oc.name AS kit_name,
    oc.id AS kit_id,
    hotlist.plate AS hotlist_plate,
    hotlist.us_state AS hotlist_us_state,
    hotlist.integration_id,
    hotlist.vin,
    iv.name AS hotlist_name,
    iv.shared AS hotlist_is_shared,
    iv.org_id AS hotlist_orgid,
    ode.id,
    ode.org_id,
    ode.name,
    ode.description,
    ode.schema,
    ode.status,
    ode.forwarding_type,
    ode.dataset,
    ode.properties,
    ode.created_at,
    ode.updated_at,
    ode.deleted_at,
    scans.ocr AS scan_ocr,
    scans.us_state AS scan_us_state,
    kits.kit_mapping
   FROM (((((((public.hits
     JOIN public.hotlist ON ((hotlist.id = hits.hotlist_id)))
     JOIN public.scans ON ((scans.id = hits.scan_id)))
     JOIN public.kits ON ((kits.id = scans.kit_id)))
     JOIN public.org_data_export_settings ode ON (((((ode.properties -> 'hotlists'::text) @> jsonb_build_array((hotlist.integration_id)::text)) OR (jsonb_array_length((ode.properties -> 'hotlists'::text)) = 0)) AND (ode.dataset = 1) AND (ode.deleted_at IS NULL) AND (ode.status = 1))))
     LEFT JOIN LATERAL ( SELECT json_object_agg(scans_meta.meta_type, scans_meta.meta_value) AS metadata
           FROM public.scans_meta
          WHERE (scans.id = scans_meta.scan_id)) sm ON (true))
     JOIN LATERAL overwatch.org_cameras(ode.org_id) oc(id, name, kit_type, org_id, is_commercial, is_shared) ON ((oc.id = scans.kit_id)))
     JOIN public.integrations_view iv ON (((iv.org_id = ode.org_id) AND (iv.id = hotlist.integration_id))));


--
-- Name: org_data_export_scans; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_data_export_scans AS
 SELECT scans.guid AS scan_guid,
    scans.id AS scan_id,
    scans.geo AS scan_geo,
    scans.scanned_at AS scan_scanned_at,
    (sm.metadata ->> '1'::text) AS vehicle_type,
    (sm.metadata ->> '2'::text) AS vehicle_color,
    (sm.metadata ->> '3'::text) AS vehicle_make,
    (sm.metadata ->> '4'::text) AS scan_address,
    public.st_x((scans.geo)::public.geometry) AS scan_longitude,
    public.st_y((scans.geo)::public.geometry) AS scan_latitude,
    oc.is_commercial AS scan_is_commercial,
    oc.is_shared AS scan_is_shared,
    oc.name AS kit_name,
    oc.id AS kit_id,
    ode.id,
    ode.org_id,
    ode.name,
    ode.description,
    ode.schema,
    ode.status,
    ode.forwarding_type,
    ode.dataset,
    ode.properties,
    scans.ocr,
    scans.us_state,
    kits.kit_mapping
   FROM ((((((public.scans
     LEFT JOIN LATERAL ( SELECT json_object_agg(scans_meta.meta_type, scans_meta.meta_value) AS metadata
           FROM public.scans_meta
          WHERE (scans.id = scans_meta.scan_id)) sm ON (true))
     JOIN overwatch.cameras ON ((cameras.id = scans.kit_id)))
     JOIN public.kits ON ((kits.id = cameras.id)))
     JOIN overwatch.locations ON ((locations.id = cameras.location_id)))
     JOIN public.org_data_export_settings ode ON ((((ode.properties -> 'sites'::text) @> jsonb_build_array((locations.site_id)::text)) AND (ode.dataset = 0) AND (ode.status = 1) AND (ode.deleted_at IS NULL))))
     JOIN LATERAL overwatch.org_cameras(ode.org_id, false, true) oc(id, name, kit_type, org_id, is_commercial, is_shared) ON ((oc.id = scans.kit_id)))
  WHERE ((scans.scanned_at >= (now() - '1 day'::interval)) AND (scans.scanned_at <= now()));


--
-- Name: org_data_export_scans_andrew_testing; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.org_data_export_scans_andrew_testing AS
 SELECT scans.guid AS scan_guid,
