--
-- Name: recovery_address; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.recovery_address AS
 SELECT id,
    row_number,
    address_id,
    geo,
    road,
    house_number,
    state,
    city,
    postcode
   FROM ( SELECT hotlist_address.hotlist_id AS id,
            row_number() OVER (PARTITION BY hotlist_address.hotlist_id ORDER BY hotlist_address.address_id) AS row_number,
            a.id AS address_id,
            a.geo,
            a.road,
            a.house_number,
            a.state,
            a.city,
            a.postcode
           FROM (public.hotlist_address
             JOIN public.address a ON ((a.id = hotlist_address.address_id)))
          WHERE (a.type_id = 2)) t
  WHERE (row_number = 1)
  WITH NO DATA;


--
-- Name: recoveries; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.recoveries
WITH (autovacuum_vacuum_scale_factor='0.025', autovacuum_analyze_scale_factor='0.015') AS
 SELECT hotlist.id,
    hotlist.integration_id,
    hotlist.remote_order_id,
    hotlist.status,
    hotlist.org_id,
    hotlist.client_org_id,
    hotlist.lienholder_org_id,
    hotlist.order_type,
    hotlist.is_staged,
    hotlist.plate,
    hotlist.us_state,
    hotlist.vin,
    hotlist.vehicle_year,
    hotlist.vehicle_make,
    hotlist.vehicle_model,
    hotlist.lookback_days,
    hotlist.created_at,
    hotlist.updated_at,
    recovery_address.address_id,
    recovery_address.house_number,
    recovery_address.road,
    recovery_address.city,
    recovery_address.state,
    recovery_address.postcode,
    recovery_address.geo,
    hotlist_meta.repo_date
   FROM ((public.hotlist
     LEFT JOIN public.recovery_address ON ((recovery_address.id = hotlist.id)))
     JOIN public.hotlist_meta ON ((hotlist_meta.hotlist_id = hotlist.id)))
  WHERE ((hotlist.status = 3) AND (hotlist_meta.repo_date IS NOT NULL))
  WITH NO DATA;


--
-- Name: repo_scan_report; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.repo_scan_report AS
 SELECT kits.id,
    kits.name,
    kits.org_id,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '1 year'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS one_year,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '04:00:00'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS four_hour,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '1 day'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS one_day,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '7 days'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS seven_day,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '30 days'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS thirty_day,
    sum(
        CASE
            WHEN (aggregate_scan_count_h.scanned_at > (now() - '01:00:00'::interval)) THEN aggregate_scan_count_h.scan_count
            ELSE 0
        END) AS one_hour
   FROM (public.kits
     JOIN public.aggregate_scan_count_h ON ((aggregate_scan_count_h.kit_id = kits.id)))
  GROUP BY kits.name, kits.id, kits.org_id;


