--
-- Name: staging_orgs_hotlist_count; Type: MATERIALIZED VIEW; Schema: public; Owner: -
--

CREATE MATERIALIZED VIEW public.staging_orgs_hotlist_count AS
 WITH staging_orgs AS (
         SELECT DISTINCT approval_list.staging_org_id AS org_id
           FROM public.approval_list
        )
 SELECT org_id,
    ( SELECT count(DISTINCT hotlist.plate) AS count
           FROM public.hotlist
          WHERE ((hotlist.org_id = staging_orgs.org_id) AND (length((hotlist.plate)::text) > 3) AND (hotlist.is_staged = true) AND (hotlist.status = 1))) AS total
   FROM staging_orgs
  WITH NO DATA;


