--
-- Name: repo_company_hotlist_30d_counts; Type: VIEW; Schema: reports; Owner: -
--

CREATE VIEW reports.repo_company_hotlist_30d_counts AS
 WITH orgs_we_care_about AS MATERIALIZED (
         SELECT orgs.id,
            orgs.name,
            sum(aggregate_scan_count_h.scan_count) AS thirty_day_scan_count
           FROM ((public.orgs
             JOIN public.kits ON ((kits.org_id = orgs.id)))
             JOIN public.aggregate_scan_count_h ON ((aggregate_scan_count_h.kit_id = kits.id)))
          WHERE ((orgs.type = 1) AND (orgs.enable_genetech_hotlist OR orgs.enable_matrix_hotlist) AND (aggregate_scan_count_h.scanned_at >= (now() - '1 mon'::interval)))
          GROUP BY orgs.id, orgs.name
        ), org_hl_d AS MATERIALIZED (
         SELECT orgs_we_care_about.id,
            orgs_we_care_about.name,
            orgs_we_care_about.thirty_day_scan_count,
            hotlist_count.hotlist_count
           FROM (orgs_we_care_about
             LEFT JOIN LATERAL ( SELECT count(DISTINCT hotlist.plate) AS hotlist_count
                   FROM public.hotlist
                  WHERE ((hotlist.org_id = orgs_we_care_about.id) AND (hotlist.status = 1) AND ((hotlist.plate)::text <> ''::text) AND (length((hotlist.plate)::text) > 3))) hotlist_count ON (true))
        ), hotlist_staged_count AS MATERIALIZED (
         WITH hls AS (
                 SELECT DISTINCT approval_list.staging_org_id
                   FROM public.approval_list
                )
         SELECT hotlist.org_id,
            count(DISTINCT hotlist.plate) AS total
           FROM (hls
             JOIN public.hotlist ON ((hotlist.org_id = hls.staging_org_id)))
          WHERE ((hotlist.status = 1) AND (hotlist.is_staged = true) AND ((hotlist.plate)::text <> ''::text) AND (length((hotlist.plate)::text) > 3))
          GROUP BY hotlist.org_id
        )
 SELECT org_hl_d.id,
    org_hl_d.name,
    org_hl_d.thirty_day_scan_count,
    org_hl_d.hotlist_count,
    staged.staged_hotlist_count
   FROM (org_hl_d
     LEFT JOIN LATERAL ( SELECT sum(hotlist_staged_count.total) AS staged_hotlist_count
           FROM (public.approval_list
             JOIN hotlist_staged_count ON ((hotlist_staged_count.org_id = approval_list.staging_org_id)))
          WHERE (approval_list.agent_org_id = org_hl_d.id)) staged ON (true));


