--
-- Name: ignored_inactive_cameras; Type: VIEW; Schema: tierzero; Owner: -
--

CREATE VIEW tierzero.ignored_inactive_cameras AS
 SELECT overwatch_cameras.id AS "Camera ID",
    overwatch_cameras.flakey AS "Unreliable",
    COALESCE((overwatch_cameras.properties ->> 'pepwave_external_ip'::text), (overwatch_cameras.properties ->> 'ip_address'::text)) AS "Public IP",
        CASE
            WHEN (overwatch_cameras.kit_type = 1) THEN 'Genetec Mobile'::text
            WHEN (overwatch_cameras.kit_type = 2) THEN 'Matrix Edge'::text
            WHEN (overwatch_cameras.kit_type = 3) THEN 'Genetec CloudRunner'::text
            WHEN (overwatch_cameras.kit_type = 4) THEN 'Defender Q (Milesight)'::text
            WHEN (overwatch_cameras.kit_type = 5) THEN 'Up4Repo'::text
            WHEN (overwatch_cameras.kit_type = 6) THEN 'Axis'::text
            WHEN (overwatch_cameras.kit_type = 7) THEN 'PIPS'::text
            WHEN (overwatch_cameras.kit_type = 8) THEN 'MX Defender'::text
            WHEN (overwatch_cameras.kit_type = 9) THEN 'MX Defender Solar'::text
            WHEN (overwatch_cameras.kit_type = 10) THEN 'Vaxtor'::text
            ELSE 'tierzero.kit_type.unknown'::text
        END AS "Kit Type",
    overwatch_cameras.name AS "Camera Name",
    overwatch_cameras.org_id AS "Org ID",
    orgs.name AS "Org Name",
    round(ag_before.scan_average) AS "Average Scans Previous Hour",
    round(ag_current.scan_average) AS "Average Scans Current Hour",
    round(ag_after.scan_average) AS "Average Scans Next Hour"
   FROM ((((overwatch.overwatch_cameras
     JOIN ( SELECT aggregate_scan_count_h.kit_id,
            EXTRACT(hour FROM aggregate_scan_count_h.scanned_at) AS hour,
            avg(aggregate_scan_count_h.scan_count) AS scan_average
           FROM public.aggregate_scan_count_h
          WHERE ((aggregate_scan_count_h.scanned_at > (now() - '7 days'::interval)) AND (EXTRACT(hour FROM (now() - '01:00:00'::interval)) = EXTRACT(hour FROM aggregate_scan_count_h.scanned_at)))
          GROUP BY aggregate_scan_count_h.kit_id, (EXTRACT(hour FROM aggregate_scan_count_h.scanned_at))) ag_before ON (((overwatch_cameras.id = ag_before.kit_id) AND (ag_before.hour = EXTRACT(hour FROM (now() - '01:00:00'::interval))))))
     JOIN ( SELECT aggregate_scan_count_h.kit_id,
            EXTRACT(hour FROM aggregate_scan_count_h.scanned_at) AS hour,
            avg(aggregate_scan_count_h.scan_count) AS scan_average
           FROM public.aggregate_scan_count_h
          WHERE (aggregate_scan_count_h.scanned_at > (now() - '7 days'::interval))
          GROUP BY aggregate_scan_count_h.kit_id, (EXTRACT(hour FROM aggregate_scan_count_h.scanned_at))) ag_current ON (((overwatch_cameras.id = ag_current.kit_id) AND (ag_current.hour = EXTRACT(hour FROM now())))))
     JOIN ( SELECT aggregate_scan_count_h.kit_id,
            EXTRACT(hour FROM aggregate_scan_count_h.scanned_at) AS hour,
            avg(aggregate_scan_count_h.scan_count) AS scan_average
           FROM public.aggregate_scan_count_h
          WHERE ((aggregate_scan_count_h.scanned_at > (now() - '7 days'::interval)) AND (EXTRACT(hour FROM (now() + '01:00:00'::interval)) = EXTRACT(hour FROM aggregate_scan_count_h.scanned_at)))
          GROUP BY aggregate_scan_count_h.kit_id, (EXTRACT(hour FROM aggregate_scan_count_h.scanned_at))) ag_after ON (((overwatch_cameras.id = ag_after.kit_id) AND (ag_after.hour = EXTRACT(hour FROM (now() + '01:00:00'::interval))))))
     JOIN public.orgs ON ((overwatch_cameras.org_id = orgs.id)))
  WHERE ((overwatch_cameras.disposition = 1) AND (overwatch_cameras.status = 2) AND (overwatch_cameras.status_notification IS NULL) AND ((ag_before.scan_average <= (20)::numeric) OR (ag_current.scan_average <= (20)::numeric) OR (ag_after.scan_average <= (20)::numeric)));


--
-- Name: VIEW ignored_inactive_cameras; Type: COMMENT; Schema: tierzero; Owner: -
--

COMMENT ON VIEW tierzero.ignored_inactive_cameras IS 'Cameras that are currently not active, but also send a historical low average of scans at the current hour - so they''re being ignored by TierZero';


