--
-- Name: premade_geozones; Type: MATERIALIZED VIEW; Schema: overwatch; Owner: -
--

CREATE MATERIALIZED VIEW overwatch.premade_geozones AS
 SELECT 'State'::public.citext AS type,
    state_all.gid AS id,
    (state_all.name)::public.citext AS name,
    json_build_object('type', 'FeatureCollection', 'features', json_agg(json_build_object('type', 'Feature', 'geometry', (public.st_asgeojson(dumped_geoms.geom))::json, 'properties', json_build_object('id', state_all.gid, 'name', state_all.name)))) AS feature_collection
   FROM tiger_data.state_all,
    LATERAL public.st_dump(state_all.simplified_geom) dumped_geoms(path, geom)
  GROUP BY state_all.gid, state_all.name
UNION ALL
 SELECT 'County'::public.citext AS type,
    tl_2019_us_county.id,
    ((((tl_2019_us_county.namelsad)::public.citext)::text || ', '::text) || ((state_all.name)::public.citext)::text) AS name,
    json_build_object('type', 'FeatureCollection', 'features', json_agg(json_build_object('type', 'Feature', 'geometry', (public.st_asgeojson(dumped_geoms.geom))::json, 'properties', json_build_object('id', tl_2019_us_county.id, 'name', tl_2019_us_county.namelsad, 'state_name', state_all.name)))) AS feature_collection
   FROM (tiger_data.tl_2019_us_county
     JOIN tiger_data.state_all ON (((tl_2019_us_county.statefp)::text = (state_all.statefp)::text))),
    LATERAL public.st_dump(public.st_simplify(public.st_transform(tl_2019_us_county.geom, 4326), (0.001)::double precision)) dumped_geoms(path, geom)
  GROUP BY tl_2019_us_county.id, tl_2019_us_county.namelsad, state_all.name
UNION ALL
 SELECT 'City'::public.citext AS type,
    cityboun.ogc_fid AS id,
    ((((cityboun.name)::public.citext)::text || ', '::text) || (cityboun.st)::text) AS name,
    json_build_object('type', 'FeatureCollection', 'features', json_agg(json_build_object('type', 'Feature', 'geometry', (public.st_asgeojson(dumped_geoms.geom))::json, 'properties', json_build_object('id', cityboun.ogc_fid, 'name', cityboun.name)))) AS feature_collection
   FROM tiger.cityboun,
    LATERAL public.st_dump(public.st_simplify(public.st_transform(cityboun.geom, 4326), (0.001)::double precision)) dumped_geoms(path, geom)
  GROUP BY cityboun.ogc_fid
UNION ALL
 SELECT 'MSA'::public.citext AS type,
    us_urban_area.ogc_fid AS id,
    (us_urban_area.name10)::public.citext AS name,
    json_build_object('type', 'FeatureCollection', 'features', json_agg(json_build_object('type', 'Feature', 'geometry', (public.st_asgeojson(dumped_geoms.geom))::json, 'properties', json_build_object('id', us_urban_area.ogc_fid, 'name', us_urban_area.name10)))) AS feature_collection
   FROM tiger_data.us_urban_area,
    LATERAL public.st_dump(public.st_simplify(public.st_transform(us_urban_area.geom_4326, 4326), (0.001)::double precision)) dumped_geoms(path, geom)
  GROUP BY us_urban_area.ogc_fid, us_urban_area.name10
  WITH NO DATA;


